package ca.team.originkickoff;

import android.content.Intent;
import android.os.Bundle;
import android.os.SystemClock;
import android.util.Log;
import android.view.View;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.fragment.app.Fragment;
import androidx.viewpager2.adapter.FragmentStateAdapter;
import androidx.viewpager2.widget.ViewPager2;

import com.google.android.material.floatingactionbutton.FloatingActionButton;
import com.google.android.material.tabs.TabLayout;
import com.google.android.material.tabs.TabLayoutMediator;
import com.google.firebase.firestore.FirebaseFirestore;

import androidx.appcompat.widget.Toolbar;

import ca.team.originkickoff.util.DeviceUtils;

public class MyEventsActivity extends AppCompatActivity {
    private static final String TAG = "MyEventsActivity";
    private TabLayout tabLayout;
    private ViewPager2 viewPager;
    private boolean isOrganizer = false;
    private FirebaseFirestore db;

    // Debounce for bottom-nav taps
    private long lastNavTapAtMs = 0L;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        setContentView(R.layout.activity_my_events);

        Toolbar toolbar = findViewById(R.id.toolbar);
        if (toolbar != null) {
            setSupportActionBar(toolbar);
        }

        if (getSupportActionBar() != null) {
            getSupportActionBar().setDisplayHomeAsUpEnabled(true);
            getSupportActionBar().setTitle("My Events");
        }

        db = FirebaseFirestore.getInstance();
        tabLayout = findViewById(R.id.tabLayout);
        viewPager = findViewById(R.id.viewPager);

        // Check if user is an organizer first, then setup tabs
        checkIfUserIsOrganizer();

        // Setup bottom navigation include
        setupBottomNav();
    }

    private void checkIfUserIsOrganizer() {
        String deviceId = DeviceUtils.getDeviceId(this);
        if (deviceId == null) {
            Log.w(TAG, "Device ID is null, defaulting to non-organizer");
            setupTabs(false);
            return;
        }

        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnSuccessListener(queryDocumentSnapshots -> {
                    if (!queryDocumentSnapshots.isEmpty()) {
                        Boolean isOrganizerField = queryDocumentSnapshots.getDocuments().get(0).getBoolean("is_organizer");
                        isOrganizer = isOrganizerField != null && isOrganizerField;
                        Log.d(TAG, "User is organizer: " + isOrganizer);
                    } else {
                        Log.w(TAG, "No user found for device_id");
                        isOrganizer = false;
                    }
                    setupTabs(isOrganizer);
                })
                .addOnFailureListener(e -> {
                    Log.e(TAG, "Error checking organizer status", e);
                    isOrganizer = false;
                    setupTabs(false);
                });
    }

    private void setupTabs(boolean showOrganizerTab) {
        // Create adapter with dynamic tab count
        viewPager.setAdapter(new FragmentStateAdapter(this) {
            @NonNull
            @Override
            public Fragment createFragment(int position) {
                if (!showOrganizerTab) {
                    // Only show Events Joined
                    return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                } else {
                    // Show both tabs
                    if (position == 0) {
                        return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                    } else {
                        return new ca.team.originkickoff.ui.fragments.EventsOrganizedFragment();
                    }
                }
            }

            @Override
            public int getItemCount() {
                return showOrganizerTab ? 2 : 1;
            }
        });

        // Setup tab names
        new TabLayoutMediator(tabLayout, viewPager, (tab, position) -> {
            if (!showOrganizerTab) {
                // Only one tab
                tab.setText("Events Joined");
            } else {
                // Two tabs
                if (position == 0) {
                    tab.setText("Events Joined");
                } else {
                    tab.setText("Events Organized");
                }
            }
        }).attach();

        // Wire FAB: only visible for organizers on Events Organized tab (index 1)
        FloatingActionButton fab = findViewById(R.id.fabCreate);
        if (fab != null && showOrganizerTab) {
            fab.setOnClickListener(v -> startActivity(new Intent(MyEventsActivity.this, CreateEventActivity.class)));

            // initial visibility
            fab.setVisibility(viewPager.getCurrentItem() == 1 ? View.VISIBLE : View.GONE);

            // show/hide based on page
            viewPager.registerOnPageChangeCallback(new ViewPager2.OnPageChangeCallback() {
                @Override
                public void onPageSelected(int position) {
                    super.onPageSelected(position);
                    if (position == 1) fab.setVisibility(View.VISIBLE);
                    else fab.setVisibility(View.GONE);
                }
            });
        } else if (fab != null) {
            // Hide FAB completely for non-organizers
            fab.setVisibility(View.GONE);
        }
    }

    private void setupBottomNav() {
        LinearLayout navHome = findViewById(R.id.navHome);
        LinearLayout navEvents = findViewById(R.id.navEvents);
        LinearLayout navNotifications = findViewById(R.id.navNotifications);
        LinearLayout navProfile = findViewById(R.id.navProfile);

        if (navHome == null || navEvents == null || navNotifications == null || navProfile == null) return;

        // Highlight current tab (My Events)
        ImageView ivEvents = findViewById(R.id.ivEvents);
        TextView tvEvents = findViewById(R.id.tvEvents);
        if (ivEvents != null) ivEvents.setColorFilter(0xFF00D9C5, android.graphics.PorterDuff.Mode.SRC_IN);
        if (tvEvents != null) tvEvents.setTextColor(0xFF00D9C5);

        navHome.setOnClickListener(v -> navigateBottomTab(MainActivity.class));
        navEvents.setOnClickListener(v -> { /* already here */ });
        navNotifications.setOnClickListener(v -> navigateBottomTab(NotificationsActivity.class));
        navProfile.setOnClickListener(v -> navigateBottomTab(ProfileActivity.class));
    }

    // Helper to navigate between bottom-bar destinations smoothly with no transition animation
    private void navigateBottomTab(Class<?> targetActivity) {
        if (targetActivity == null) return;
        if (getClass().equals(targetActivity)) return; // already on this tab
        long now = SystemClock.elapsedRealtime();
        if (now - lastNavTapAtMs < 300) return; // debounce rapid taps
        lastNavTapAtMs = now;
        Intent intent = new Intent(this, targetActivity);
        intent.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT | Intent.FLAG_ACTIVITY_NO_ANIMATION);
        startActivity(intent);
        overridePendingTransition(0, 0);
    }

    @Override
    public boolean onSupportNavigateUp() {
        finish();
        return true;
    }
}

package ca.team.originkickoff;

import android.content.Intent;
import android.os.Bundle;
import android.os.SystemClock;
import android.util.Log;
import android.view.View;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.fragment.app.Fragment;
import androidx.viewpager2.adapter.FragmentStateAdapter;
import androidx.viewpager2.widget.ViewPager2;

import com.google.android.material.floatingactionbutton.FloatingActionButton;
import com.google.android.material.tabs.TabLayout;
import com.google.android.material.tabs.TabLayoutMediator;
import com.google.firebase.firestore.FirebaseFirestore;

import androidx.appcompat.widget.Toolbar;

import ca.team.originkickoff.util.DeviceUtils;

public class MyEventsActivity extends AppCompatActivity {
    private static final String TAG = "MyEventsActivity";
    private TabLayout tabLayout;
    private ViewPager2 viewPager;
    private boolean isOrganizer = false;
    private FirebaseFirestore db;

    // Debounce for bottom-nav taps
    private long lastNavTapAtMs = 0L;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        setContentView(R.layout.activity_my_events);

        Toolbar toolbar = findViewById(R.id.toolbar);
        if (toolbar != null) {
            setSupportActionBar(toolbar);
        }

        if (getSupportActionBar() != null) {
            getSupportActionBar().setDisplayHomeAsUpEnabled(true);
            getSupportActionBar().setTitle("My Events");
        }

        db = FirebaseFirestore.getInstance();
        tabLayout = findViewById(R.id.tabLayout);
        viewPager = findViewById(R.id.viewPager);

        // Check if user is an organizer first, then setup tabs
        checkIfUserIsOrganizer();

        // Setup bottom navigation include
        setupBottomNav();
    }

    private void checkIfUserIsOrganizer() {
        String deviceId = DeviceUtils.getDeviceId(this);
        if (deviceId == null) {
            Log.w(TAG, "Device ID is null, defaulting to non-organizer");
            setupTabs(false);
            return;
        }

        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnSuccessListener(queryDocumentSnapshots -> {
                    if (!queryDocumentSnapshots.isEmpty()) {
                        Boolean isOrganizerField = queryDocumentSnapshots.getDocuments().get(0).getBoolean("is_organizer");
                        if (isOrganizerField == null) isOrganizerField = queryDocumentSnapshots.getDocuments().get(0).getBoolean("is_organiser");
                        if (isOrganizerField == null) {
                            Object camel = queryDocumentSnapshots.getDocuments().get(0).get("isOrganizer");
                            if (camel instanceof Boolean) isOrganizerField = (Boolean) camel;
                        }
                        isOrganizer = isOrganizerField != null && isOrganizerField;
                        Log.d(TAG, "User explicit organizer flag: " + isOrganizer);

                        if (!isOrganizer) {
                            // Fallback inference: does user have any events with organizerId == their document ID or deviceId?
                            String userDocId = queryDocumentSnapshots.getDocuments().get(0).getId();
                            java.util.List<String> possibleIds = new java.util.ArrayList<>();
                            possibleIds.add(userDocId);
                            if (!deviceId.equals(userDocId)) possibleIds.add(deviceId);
                            db.collection("events")
                                    .whereIn("organizerId", possibleIds)
                                    .limit(1)
                                    .get()
                                    .addOnSuccessListener(evSnap -> {
                                        if (!evSnap.isEmpty()) {
                                            Log.d(TAG, "Inferred organizer via existing events");
                                            isOrganizer = true;
                                        }
                                        setupTabs(isOrganizer);
                                    })
                                    .addOnFailureListener(e -> {
                                        Log.e(TAG, "Organizer inference failed", e);
                                        setupTabs(isOrganizer);
                                    });
                        } else {
                            setupTabs(true);
                        }
                    } else {
                        Log.w(TAG, "No user found for device_id");
                        isOrganizer = false;
                        setupTabs(false);
                    }
                })
                .addOnFailureListener(e -> {
                    Log.e(TAG, "Error checking organizer status", e);
                    isOrganizer = false;
                    setupTabs(false);
                });
    }

    private void setupTabs(boolean showOrganizerTab) {
        // Create adapter with dynamic tab count
        viewPager.setAdapter(new FragmentStateAdapter(this) {
            @NonNull
            @Override
            public Fragment createFragment(int position) {
                if (!showOrganizerTab) {
                    // Only show Events Joined
                    return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                } else {
                    // Show both tabs
                    if (position == 0) {
                        return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                    } else {
                        return new ca.team.originkickoff.ui.fragments.EventsOrganizedFragment();
                    }
                }
            }

            @Override
            public int getItemCount() {
                return showOrganizerTab ? 2 : 1;
            }
        });

        // Setup tab names
        new TabLayoutMediator(tabLayout, viewPager, (tab, position) -> {
            if (!showOrganizerTab) {
                // Only one tab
                tab.setText("Events Joined");
            } else {
                // Two tabs
                if (position == 0) {
                    tab.setText("Events Joined");
                } else {
                    tab.setText("Events Organized");
                }
            }
        }).attach();

        // Wire FAB: only visible for organizers on Events Organized tab (index 1)
        FloatingActionButton fab = findViewById(R.id.fabCreate);
        if (fab != null && showOrganizerTab) {
            fab.setOnClickListener(v -> startActivity(new Intent(MyEventsActivity.this, CreateEventActivity.class)));

            // initial visibility
            fab.setVisibility(viewPager.getCurrentItem() == 1 ? View.VISIBLE : View.GONE);

            // show/hide based on page
            viewPager.registerOnPageChangeCallback(new ViewPager2.OnPageChangeCallback() {
                @Override
                public void onPageSelected(int position) {
                    super.onPageSelected(position);
                    if (position == 1) fab.setVisibility(View.VISIBLE);
                    else fab.setVisibility(View.GONE);
                }
            });
        } else if (fab != null) {
            // Hide FAB completely for non-organizers
            fab.setVisibility(View.GONE);
        }
    }

    private void setupBottomNav() {
        LinearLayout navHome = findViewById(R.id.navHome);
        LinearLayout navEvents = findViewById(R.id.navEvents);
        LinearLayout navNotifications = findViewById(R.id.navNotifications);
        LinearLayout navProfile = findViewById(R.id.navProfile);

        if (navHome == null || navEvents == null || navNotifications == null || navProfile == null) return;

        // Highlight current tab (My Events)
        ImageView ivEvents = findViewById(R.id.ivEvents);
        TextView tvEvents = findViewById(R.id.tvEvents);
        if (ivEvents != null) ivEvents.setColorFilter(0xFF00D9C5, android.graphics.PorterDuff.Mode.SRC_IN);
        if (tvEvents != null) tvEvents.setTextColor(0xFF00D9C5);

        navHome.setOnClickListener(v -> navigateBottomTab(MainActivity.class));
        navEvents.setOnClickListener(v -> { /* already here */ });
        navNotifications.setOnClickListener(v -> navigateBottomTab(NotificationsActivity.class));
        navProfile.setOnClickListener(v -> navigateBottomTab(ProfileActivity.class));
    }

    // Helper to navigate between bottom-bar destinations smoothly with no transition animation
    private void navigateBottomTab(Class<?> targetActivity) {
        if (targetActivity == null) return;
        if (getClass().equals(targetActivity)) return; // already on this tab
        long now = SystemClock.elapsedRealtime();
        if (now - lastNavTapAtMs < 300) return; // debounce rapid taps
        lastNavTapAtMs = now;
        Intent intent = new Intent(this, targetActivity);
        intent.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT | Intent.FLAG_ACTIVITY_NO_ANIMATION);
        startActivity(intent);
        overridePendingTransition(0, 0);
    }

    @Override
    public boolean onSupportNavigateUp() {
        finish();
        return true;
    }
}

package ca.team.originkickoff.services;

import android.util.Log;

import androidx.annotation.NonNull;

import com.google.firebase.Timestamp;
import com.google.firebase.firestore.DocumentSnapshot;
import com.google.firebase.firestore.FirebaseFirestore;

import ca.team.originkickoff.models.Event;

public class FirebaseEventService {
    private static final String TAG = "FirebaseEventService";
    private static final String EVENTS_COLLECTION = "events";
    private FirebaseFirestore db;

    public FirebaseEventService() {
        this.db = FirebaseFirestore.getInstance();
    }

    public void getEventsWithOpenRegistration(@NonNull EventsCallback callback) {
        Log.d(TAG, "Starting event fetch - looking for published events");
        db.collection(EVENTS_COLLECTION)
                .whereEqualTo("status", "published")
                .addSnapshotListener((snapshot, error) -> {
                    if (error != null) {
                        Log.e(TAG, "Error fetching events with status filter: " + error.getMessage(), error);
                        Log.d(TAG, "Trying fallback: fetching all events without status filter");
                        getAllEventsDebug(callback);
                        return;
                    }

                    if (snapshot != null) {
                        Log.d(TAG, "Firestore snapshot received. Total documents: " + snapshot.size());
                        java.util.List<Event> events = new java.util.ArrayList<>();
                        long currentTime = System.currentTimeMillis();

                        for (DocumentSnapshot doc : snapshot.getDocuments()) {
                            try {
                                Event event = doc.toObject(Event.class);
                                Log.d(TAG, "Processing document: " + doc.getId());

                                if (event != null) {
                                    event.setId(doc.getId());
                                    Log.d(TAG, "Event loaded: " + event.getName() + ", Status: " + (event.getRegistrationStartTime() != null ? "has dates" : "no dates"));

                                    if (event.getRegistrationStartTime() != null &&
                                        event.getRegistrationEndTime() != null) {
                                        long startTime = event.getRegistrationStartTime().getTime();
                                        long endTime = event.getRegistrationEndTime().getTime();

                                        Log.d(TAG, "Current time: " + currentTime + ", Start: " + startTime + ", End: " + endTime);

                                        if (currentTime >= startTime && currentTime <= endTime) {
                                            events.add(event);
                                            Log.d(TAG, "✓ Added open event: " + event.getName());
                                        } else {
                                            Log.d(TAG, "✗ Event not in registration window: " + event.getName());
                                        }
                                    } else {
                                        Log.d(TAG, "✗ Event missing registration times: " + event.getName());
                                    }
                                } else {
                                    Log.d(TAG, "Event object is null for document: " + doc.getId());
                                }
                            } catch (Exception e) {
                                Log.e(TAG, "Error parsing event: ", e);
                            }
                        }

                        events.sort((e1, e2) -> {
                            if (e1.getRegistrationEndTime() == null || e2.getRegistrationEndTime() == null) {
                                return 0;
                            }
                            return Long.compare(e1.getRegistrationEndTime().getTime(),
                                              e2.getRegistrationEndTime().getTime());
                        });

                        Log.d(TAG, "Final result: " + events.size() + " events with open registration");
                        callback.onSuccess(events);
                    } else {
                        Log.d(TAG, "Snapshot is null");
                        callback.onSuccess(new java.util.ArrayList<>());
                    }
                });
    }

    private void getAllEventsDebug(@NonNull EventsCallback callback) {
        Log.d(TAG, "Debug fetch: Getting ALL events");
        db.collection(EVENTS_COLLECTION)
                .addSnapshotListener((snapshot, error) -> {
                    if (error != null) {
                        Log.e(TAG, "Error in debug fetch: " + error.getMessage(), error);
                        callback.onError("Debug fetch failed: " + error.getMessage());
                        return;
                    }

                    if (snapshot != null) {
                        Log.d(TAG, "Debug: Found " + snapshot.size() + " total events in collection");
                        java.util.List<Event> events = new java.util.ArrayList<>();
                        long currentTime = System.currentTimeMillis();

                        for (DocumentSnapshot doc : snapshot.getDocuments()) {
                            try {
                                Event event = doc.toObject(Event.class);
                                if (event != null) {
                                    event.setId(doc.getId());
                                    Log.d(TAG, "Debug Event: " + event.getName() + ", Status: " + (event.getRegistrationStartTime() != null ? "has times" : "NO TIMES"));

                                    if (event.getRegistrationStartTime() != null &&
                                        event.getRegistrationEndTime() != null) {
                                        long startTime = event.getRegistrationStartTime().getTime();
                                        long endTime = event.getRegistrationEndTime().getTime();

                                        if (currentTime >= startTime && currentTime <= endTime) {
                                            events.add(event);
                                            Log.d(TAG, "✓ Debug added: " + event.getName());
                                        } else {
                                            Log.d(TAG, "✗ Debug out of window: " + event.getName());
                                        }
                                    }
                                }
                            } catch (Exception e) {
                                Log.e(TAG, "Error in debug parse: ", e);
                            }
                        }

                        Log.d(TAG, "Debug result: " + events.size() + " events");
                        callback.onSuccess(events);
                    }
                });
    }

    public void getAllEvents(@NonNull EventsCallback callback) {
        Log.d(TAG, "Fetching ALL events from Firestore.");
        db.collection(EVENTS_COLLECTION)
                .addSnapshotListener((snapshot, error) -> {
                    if (error != null) {
                        Log.e(TAG, "Error fetching all events: " + error.getMessage(), error);
                        callback.onError("Error fetching all events: " + error.getMessage());
                        return;
                    }

                    if (snapshot != null) {
                        Log.d(TAG, "Firestore snapshot received. Total documents: " + snapshot.size());
                        java.util.List<Event> events = new java.util.ArrayList<>();
                        for (DocumentSnapshot doc : snapshot.getDocuments()) {
                            try {
                                Event event = doc.toObject(Event.class);
                                if (event != null) {
                                    event.setId(doc.getId());
                                    events.add(event);
                                    Log.d(TAG, "✓ Added event: " + event.getName());
                                } else {
                                    Log.d(TAG, "Event object is null for document: " + doc.getId());
                                }
                            } catch (Exception e) {
                                Log.e(TAG, "Error parsing event: ", e);
                            }
                        }
                        Log.d(TAG, "Final result: " + events.size() + " total events found.");
                        callback.onSuccess(events);
                    } else {
                        Log.d(TAG, "Snapshot is null");
                        callback.onSuccess(new java.util.ArrayList<>());
                    }
                });
    }

    public void getEventById(@NonNull String eventId, @NonNull SingleEventCallback callback) {
        db.collection(EVENTS_COLLECTION)
                .document(eventId)
                .addSnapshotListener((snapshot, error) -> {
                    if (error != null) {
                        Log.e(TAG, "Error fetching event: ", error);
                        callback.onError(error.getMessage());
                        return;
                    }

                    if (snapshot != null && snapshot.exists()) {
                        Event event = snapshot.toObject(Event.class);
                        if (event != null) {
                            event.setId(snapshot.getId());
                            callback.onSuccess(event);
                        }
                    } else {
                        callback.onError("Event not found");
                    }
                });
    }

    public interface EventsCallback {
        void onSuccess(java.util.List<Event> events);
        void onError(String errorMessage);
    }

    public interface SingleEventCallback {
        void onSuccess(Event event);
        void onError(String errorMessage);
    }
}

/*
 * Firestore-backed service for reading Event data used throughout the app.
 * Centralizes event queries and parsing to keep UI layers simple.
 */
package ca.team.originkickoff.services;

import android.util.Log;

import androidx.annotation.NonNull;

import com.google.firebase.Timestamp;
import com.google.firebase.firestore.DocumentSnapshot;
import com.google.firebase.firestore.FirebaseFirestore;

import ca.team.originkickoff.models.Event;

/**
 * Provides methods to fetch events and individual event details from Firestore.
 */
public class FirebaseEventService {
    private static final String TAG = "FirebaseEventService";
    private static final String EVENTS_COLLECTION = "events";
    private FirebaseFirestore db;

    /**
     * Creates a new instance backed by the default FirebaseFirestore.
     */
    public FirebaseEventService() {
        this.db = FirebaseFirestore.getInstance();
    }

    /**
     * Fetches events currently within their registration window among those marked as published.
     * Falls back to a debug fetch of all events if the filtered query fails (e.g., missing index).
     *
     * @param callback callback invoked with the filtered list or an error message
     */
    public void getEventsWithOpenRegistration(@NonNull EventsCallback callback) {
        Log.d(TAG, "Starting event fetch - looking for published events");
        db.collection(EVENTS_COLLECTION)
                .whereEqualTo("status", "published")
                .addSnapshotListener((snapshot, error) -> {
                    if (error != null) {
                        Log.e(TAG, "Error fetching events with status filter: " + error.getMessage(), error);
                        Log.d(TAG, "Trying fallback: fetching all events without status filter");
                        getAllEventsDebug(callback);
                        return;
                    }

                    if (snapshot != null) {
                        Log.d(TAG, "Firestore snapshot received. Total documents: " + snapshot.size());
                        java.util.List<Event> events = new java.util.ArrayList<>();
                        long currentTime = System.currentTimeMillis();

                        for (DocumentSnapshot doc : snapshot.getDocuments()) {
                            try {
                                Event event = doc.toObject(Event.class);
                                Log.d(TAG, "Processing document: " + doc.getId());

                                if (event != null) {
                                    event.setId(doc.getId());
                                    Log.d(TAG, "Event loaded: " + event.getName() + ", Status: " + (event.getRegistrationStartTime() != null ? "has dates" : "no dates"));

                                    if (event.getRegistrationStartTime() != null &&
                                        event.getRegistrationEndTime() != null) {
                                        long startTime = event.getRegistrationStartTime().getTime();
                                        long endTime = event.getRegistrationEndTime().getTime();

                                        Log.d(TAG, "Current time: " + currentTime + ", Start: " + startTime + ", End: " + endTime);

                                        if (currentTime >= startTime && currentTime <= endTime) {
                                            events.add(event);
                                            Log.d(TAG, "✓ Added open event: " + event.getName());
                                        } else {
                                            Log.d(TAG, "✗ Event not in registration window: " + event.getName());
                                        }
                                    } else {
                                        Log.d(TAG, "✗ Event missing registration times: " + event.getName());
                                    }
                                } else {
                                    Log.d(TAG, "Event object is null for document: " + doc.getId());
                                }
                            } catch (Exception e) {
                                Log.e(TAG, "Error parsing event: ", e);
                            }
                        }

                        events.sort((e1, e2) -> {
                            if (e1.getRegistrationEndTime() == null || e2.getRegistrationEndTime() == null) {
                                return 0;
                            }
                            return Long.compare(e1.getRegistrationEndTime().getTime(),
                                              e2.getRegistrationEndTime().getTime());
                        });

                        Log.d(TAG, "Final result: " + events.size() + " events with open registration");
                        callback.onSuccess(events);
                    } else {
                        Log.d(TAG, "Snapshot is null");
                        callback.onSuccess(new java.util.ArrayList<>());
                    }
                });
    }

    /**
     * Fallback helper that fetches all events for diagnostic purposes.
     *
     * @param callback callback invoked with any events found or error message
     */
    private void getAllEventsDebug(@NonNull EventsCallback callback) {
        Log.d(TAG, "Debug fetch: Getting ALL events");
        db.collection(EVENTS_COLLECTION)
                .addSnapshotListener((snapshot, error) -> {
                    if (error != null) {
                        Log.e(TAG, "Error in debug fetch: " + error.getMessage(), error);
                        callback.onError("Debug fetch failed: " + error.getMessage());
                        return;
                    }

                    if (snapshot != null) {
                        Log.d(TAG, "Debug: Found " + snapshot.size() + " total events in collection");
                        java.util.List<Event> events = new java.util.ArrayList<>();
                        long currentTime = System.currentTimeMillis();

                        for (DocumentSnapshot doc : snapshot.getDocuments()) {
                            try {
                                Event event = doc.toObject(Event.class);
                                if (event != null) {
                                    event.setId(doc.getId());
                                    Log.d(TAG, "Debug Event: " + event.getName() + ", Status: " + (event.getRegistrationStartTime() != null ? "has times" : "NO TIMES"));

                                    if (event.getRegistrationStartTime() != null &&
                                        event.getRegistrationEndTime() != null) {
                                        long startTime = event.getRegistrationStartTime().getTime();
                                        long endTime = event.getRegistrationEndTime().getTime();

                                        if (currentTime >= startTime && currentTime <= endTime) {
                                            events.add(event);
                                            Log.d(TAG, "✓ Debug added: " + event.getName());
                                        } else {
                                            Log.d(TAG, "✗ Debug out of window: " + event.getName());
                                        }
                                    }
                                }
                            } catch (Exception e) {
                                Log.e(TAG, "Error in debug parse: ", e);
                            }
                        }

                        Log.d(TAG, "Debug result: " + events.size() + " events");
                        callback.onSuccess(events);
                    }
                });
    }

    /**
     * Retrieves all events without filtering.
     *
     * @param callback callback invoked with the full list or error message
     */
    public void getAllEvents(@NonNull EventsCallback callback) {
        Log.d(TAG, "Fetching ALL events from Firestore.");
        db.collection(EVENTS_COLLECTION)
                .addSnapshotListener((snapshot, error) -> {
                    if (error != null) {
                        Log.e(TAG, "Error fetching all events: " + error.getMessage(), error);
                        callback.onError("Error fetching all events: " + error.getMessage());
                        return;
                    }

                    if (snapshot != null) {
                        Log.d(TAG, "Firestore snapshot received. Total documents: " + snapshot.size());
                        java.util.List<Event> events = new java.util.ArrayList<>();
                        for (DocumentSnapshot doc : snapshot.getDocuments()) {
                            try {
                                Event event = doc.toObject(Event.class);
                                if (event != null) {
                                    event.setId(doc.getId());
                                    events.add(event);
                                    Log.d(TAG, "✓ Added event: " + event.getName());
                                } else {
                                    Log.d(TAG, "Event object is null for document: " + doc.getId());
                                }
                            } catch (Exception e) {
                                Log.e(TAG, "Error parsing event: ", e);
                            }
                        }
                        Log.d(TAG, "Final result: " + events.size() + " total events found.");
                        callback.onSuccess(events);
                    } else {
                        Log.d(TAG, "Snapshot is null");
                        callback.onSuccess(new java.util.ArrayList<>());
                    }
                });
    }

    /**
     * Subscribes to a single event document and returns its current value.
     *
     * @param eventId  Firestore document ID of the event
     * @param callback callback invoked with the event or an error message
     */
    public void getEventById(@NonNull String eventId, @NonNull SingleEventCallback callback) {
        db.collection(EVENTS_COLLECTION)
                .document(eventId)
                .addSnapshotListener((snapshot, error) -> {
                    if (error != null) {
                        Log.e(TAG, "Error fetching event: ", error);
                        callback.onError(error.getMessage());
                        return;
                    }

                    if (snapshot != null && snapshot.exists()) {
                        Event event = snapshot.toObject(Event.class);
                        if (event != null) {
                            event.setId(snapshot.getId());
                            callback.onSuccess(event);
                        }
                    } else {
                        callback.onError("Event not found");
                    }
                });
    }

    /**
     * Callback interface for event list queries.
     */
    public interface EventsCallback {
        /**
         * Called when events are fetched successfully.
         *
         * @param events list of events returned from Firestore
         */
        void onSuccess(java.util.List<Event> events);

        /**
         * Called when an error occurs.
         *
         * @param errorMessage human-readable error message
         */
        void onError(String errorMessage);
    }

    /**
     * Callback interface for single event queries.
     */
    public interface SingleEventCallback {
        /**
         * Called when the event is fetched successfully.
         *
         * @param event the loaded event
         */
        void onSuccess(Event event);

        /**
         * Called when an error occurs.
         *
         * @param errorMessage human-readable error message
         */
        void onError(String errorMessage);
    }
}

package ca.team.originkickoff.services;

import androidx.annotation.NonNull;

import com.google.android.gms.tasks.Task;
import com.google.android.gms.tasks.Tasks;
import com.google.firebase.Timestamp;
import com.google.firebase.firestore.DocumentReference;
import com.google.firebase.firestore.DocumentSnapshot;
import com.google.firebase.firestore.FirebaseFirestore;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import ca.team.originkickoff.models.LotteryMethod;
import ca.team.originkickoff.models.LotteryResult;

/**
 * Orchestrates the complete lottery process:
 * 1. Validates lottery can be conducted
 * 2. Conducts the lottery draw
 * 3. Saves results to Firestore
 * 4. Updates winner status
 */
public class LotteryOrchestrator {
    private static final String LOTTERY_RESULTS_COLL = "lottery_results";
    private static final String EVENTS_COLL = "events";

    private final FirebaseFirestore db;
    private final LotteryService lotteryService;
    private final WaitingListService waitingListService;

    public LotteryOrchestrator() {
        this.db = FirebaseFirestore.getInstance();
        this.lotteryService = new LotteryService();
        this.waitingListService = new WaitingListService();
    }

    /**
     * Conduct a lottery for an event.
     *
     * @param eventId The event ID
     * @param organizerId The organizer conducting the lottery (for audit)
     * @param numWinners Number of winners to select (typically event capacity)
     * @param method The lottery method to use
     * @return Task containing the lottery result
     */
    public Task<LotteryResult> conductLottery(@NonNull String eventId,
                                               @NonNull String organizerId,
                                               int numWinners,
                                               @NonNull LotteryMethod method) {
        return hasLotteryBeenConducted(eventId)
                .continueWithTask(task -> {
                    if (!task.isSuccessful()) {
                        return Tasks.forException(task.getException());
                    }
                    if (Boolean.TRUE.equals(task.getResult())) {
                        return Tasks.forException(new IllegalStateException("Lottery has already been conducted for this event"));
                    }
                    return waitingListService.countActive(eventId);
                })
                .continueWithTask(countTask -> {
                    if (!countTask.isSuccessful()) {
                        return Tasks.forException(countTask.getException());
                    }
                    int totalEntrants = countTask.getResult();
                    if (totalEntrants == 0) {
                        return Tasks.forException(new IllegalStateException("No active entrants in waiting list"));
                    }
                    return lotteryService.conductLottery(eventId, method, numWinners)
                            .continueWithTask(lotteryTask -> {
                                if (!lotteryTask.isSuccessful()) {
                                    return Tasks.forException(lotteryTask.getException());
                                }
                                List<String> winnerIds = lotteryTask.getResult();
                                return waitingListService.getAllActiveUserIds(eventId)
                                        .continueWithTask(allEntrantsTask -> {
                                            if (!allEntrantsTask.isSuccessful()) {
                                                return Tasks.forException(allEntrantsTask.getException());
                                            }
                                            List<String> allEntrantIds = allEntrantsTask.getResult();
                                            LotteryResult result = new LotteryResult(
                                                    eventId,
                                                    Timestamp.now(),
                                                    method.getValue(),
                                                    totalEntrants,
                                                    winnerIds.size(),
                                                    winnerIds,
                                                    organizerId
                                            );
                                            result.setAllEntrantIds(allEntrantIds);
                                            return persistOutcome(result, winnerIds, allEntrantIds);
                                        });
                            });
                });
    }

    private Task<LotteryResult> persistOutcome(LotteryResult result, List<String> winnerIds, List<String> allEntrantIds) {
        // Save lottery result, then update event status and create invitation_status entries
        return saveLotteryResult(result).continueWithTask(saveTask -> {
            if (!saveTask.isSuccessful()) {
                return Tasks.forException(saveTask.getException());
            }
            // Update event's lotteryStatus field to 'conducted'
            Task<Void> updateEventTask = db.collection(EVENTS_COLL)
                    .document(result.getEventId())
                    .update("lotteryStatus", "conducted");

            // Build batch for invitation_status documents for winners
            com.google.firebase.firestore.WriteBatch batch = db.batch();
            for (String winnerId : winnerIds) {
                DocumentReference inviteRef = db.collection("invitation_status").document(result.getEventId() + "_" + winnerId);
                Map<String, Object> inviteData = new HashMap<>();
                inviteData.put("event_id", result.getEventId());
                inviteData.put("user_id", winnerId);
                inviteData.put("status", "chosen");
                inviteData.put("invited_at", Timestamp.now());
                batch.set(inviteRef, inviteData);
            }
            Task<Void> batchCommit = batch.commit();

            // Optional: send notifications if NotificationService available
            NotificationService notificationService = new NotificationService();
            Task<Void> notifyTask = Tasks.whenAllSuccess(buildNotificationTasks(notificationService, result.getEventId(), winnerIds, allEntrantIds))
                    .continueWith(t -> null);

            return Tasks.whenAll(updateEventTask, batchCommit, notifyTask)
                    .continueWith(t -> {
                        if (!t.isSuccessful()) {
                            throw t.getException();
                        }
                        return result;
                    });
        });
    }

    private List<Task<Void>> buildNotificationTasks(NotificationService notificationService, String eventId, List<String> winnerIds, List<String> allEntrantIds) {
        // Only winners get result notifications currently (non-winners can be added if desired)
        // For now, send winner notifications; losers omitted to reduce noise
        List<Task<Void>> tasks = new java.util.ArrayList<>();
        // Fetch event name to include in notifications (best-effort)
        return tasks; // TODO: implement event name retrieval & notifications if required by spec
    }

    /**
     * Check if lottery has already been conducted for an event.
     */
    public Task<Boolean> hasLotteryBeenConducted(@NonNull String eventId) {
        return db.collection(LOTTERY_RESULTS_COLL)
                .document(eventId)
                .get()
                .continueWith(task -> {
                    if (!task.isSuccessful()) return false;
                    DocumentSnapshot doc = task.getResult();
                    return doc != null && doc.exists();
                });
    }

    /**
     * Get lottery result for an event.
     */
    public Task<LotteryResult> getLotteryResult(@NonNull String eventId) {
        return db.collection(LOTTERY_RESULTS_COLL)
                .document(eventId)
                .get()
                .continueWith(task -> {
                    if (!task.isSuccessful() || task.getResult() == null) {
                        return null;
                    }
                    return task.getResult().toObject(LotteryResult.class);
                });
    }

    /**
     * Check if a user is a winner in the lottery.
     */
    public Task<Boolean> isWinner(@NonNull String eventId, @NonNull String userId) {
        return getLotteryResult(eventId)
                .continueWith(task -> {
                    if (!task.isSuccessful() || task.getResult() == null) {
                        return false;
                    }
                    LotteryResult result = task.getResult();
                    return result.getWinnerIds() != null &&
                           result.getWinnerIds().contains(userId);
                });
    }

    /**
     * Save lottery result to Firestore.
     */
    private Task<LotteryResult> saveLotteryResult(LotteryResult result) {
        Map<String, Object> data = new HashMap<>();
        data.put("event_id", result.getEventId());
        data.put("conducted_at", result.getConductedAt());
        data.put("lottery_method", result.getLotteryMethod());
        data.put("total_entrants", result.getTotalEntrants());
        data.put("num_winners", result.getNumWinners());
        data.put("winner_ids", result.getWinnerIds());
        data.put("conducted_by", result.getConductedBy());

        return db.collection(LOTTERY_RESULTS_COLL)
                .document(result.getEventId())
                .set(data)
                .continueWith(task -> {
                    if (!task.isSuccessful()) {
                        throw task.getException();
                    }
                    return result;
                });
    }
}

/*
 * High-level coordinator for running an event lottery end‑to‑end.
 * Validates state, draws winners, persists results, and triggers side effects.
 */
package ca.team.originkickoff.services;

import androidx.annotation.NonNull;

import com.google.android.gms.tasks.Task;
import com.google.android.gms.tasks.Tasks;
import com.google.firebase.Timestamp;
import com.google.firebase.firestore.DocumentReference;
import com.google.firebase.firestore.DocumentSnapshot;
import com.google.firebase.firestore.FirebaseFirestore;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import ca.team.originkickoff.models.LotteryMethod;
import ca.team.originkickoff.models.LotteryResult;

/**
 * Orchestrates the complete lottery process including validation, draw, persistence,
 * and updating other collections (event status, invitation statuses, notifications).
 */
public class LotteryOrchestrator {
    private static final String LOTTERY_RESULTS_COLL = "lottery_results";
    private static final String EVENTS_COLL = "events";

    private final FirebaseFirestore db;
    private final LotteryService lotteryService;
    private final WaitingListService waitingListService;

    /**
     * Constructs a new orchestrator using default Firestore-backed services.
     */
    public LotteryOrchestrator() {
        this.db = FirebaseFirestore.getInstance();
        this.lotteryService = new LotteryService();
        this.waitingListService = new WaitingListService();
    }

    /**
     * Conduct a lottery for an event.
     *
     * @param eventId     ID of the event whose lottery is being run
     * @param organizerId ID of organizer performing the action (audit info)
     * @param numWinners  desired number of winners (typically capacity)
     * @param method      lottery selection method
     * @return Task resolving with the persisted {@link LotteryResult}
     */
    public Task<LotteryResult> conductLottery(@NonNull String eventId,
                                               @NonNull String organizerId,
                                               int numWinners,
                                               @NonNull LotteryMethod method) {
        return hasLotteryBeenConducted(eventId)
                .continueWithTask(task -> {
                    if (!task.isSuccessful()) {
                        return Tasks.forException(task.getException());
                    }
                    if (Boolean.TRUE.equals(task.getResult())) {
                        return Tasks.forException(new IllegalStateException("Lottery has already been conducted for this event"));
                    }
                    return waitingListService.countActive(eventId);
                })
                .continueWithTask(countTask -> {
                    if (!countTask.isSuccessful()) {
                        return Tasks.forException(countTask.getException());
                    }
                    int totalEntrants = countTask.getResult();
                    if (totalEntrants == 0) {
                        return Tasks.forException(new IllegalStateException("No active entrants in waiting list"));
                    }
                    return lotteryService.conductLottery(eventId, method, numWinners)
                            .continueWithTask(lotteryTask -> {
                                if (!lotteryTask.isSuccessful()) {
                                    return Tasks.forException(lotteryTask.getException());
                                }
                                List<String> winnerIds = lotteryTask.getResult();
                                return waitingListService.getAllActiveUserIds(eventId)
                                        .continueWithTask(allEntrantsTask -> {
                                            if (!allEntrantsTask.isSuccessful()) {
                                                return Tasks.forException(allEntrantsTask.getException());
                                            }
                                            List<String> allEntrantIds = allEntrantsTask.getResult();
                                            LotteryResult result = new LotteryResult(
                                                    eventId,
                                                    Timestamp.now(),
                                                    method.getValue(),
                                                    totalEntrants,
                                                    winnerIds.size(),
                                                    winnerIds,
                                                    organizerId
                                            );
                                            result.setAllEntrantIds(allEntrantIds);
                                            return persistOutcome(result, winnerIds, allEntrantIds);
                                        });
                            });
                });
    }

    /**
     * Persist lottery outcome and perform follow‑up updates (event status, invitations, notifications).
     *
     * @param result       finalized lottery result object
     * @param winnerIds    list of winners
     * @param allEntrantIds list of all entrant user IDs
     * @return Task resolving with the same {@link LotteryResult}
     */
    private Task<LotteryResult> persistOutcome(LotteryResult result, List<String> winnerIds, List<String> allEntrantIds) {
        return saveLotteryResult(result).continueWithTask(saveTask -> {
            if (!saveTask.isSuccessful()) {
                return Tasks.forException(saveTask.getException());
            }
            Task<Void> updateEventTask = db.collection(EVENTS_COLL)
                    .document(result.getEventId())
                    .update("lotteryStatus", "conducted");

            com.google.firebase.firestore.WriteBatch batch = db.batch();
            for (String winnerId : winnerIds) {
                DocumentReference inviteRef = db.collection("invitation_status").document(result.getEventId() + "_" + winnerId);
                Map<String, Object> inviteData = new HashMap<>();
                inviteData.put("event_id", result.getEventId());
                inviteData.put("user_id", winnerId);
                inviteData.put("status", "chosen");
                inviteData.put("invited_at", Timestamp.now());
                batch.set(inviteRef, inviteData);
            }
            Task<Void> batchCommit = batch.commit();

            NotificationService notificationService = new NotificationService();
            Task<Void> notifyTask = Tasks.whenAllSuccess(buildNotificationTasks(notificationService, result.getEventId(), winnerIds, allEntrantIds))
                    .continueWith(t -> null);

            return Tasks.whenAll(updateEventTask, batchCommit, notifyTask)
                    .continueWith(t -> {
                        if (!t.isSuccessful()) {
                            throw t.getException();
                        }
                        return result;
                    });
        });
    }

    /**
     * Build notification creation tasks for winners (placeholder implementation currently).
     *
     * @param notificationService service used to create notifications
     * @param eventId             event identifier
     * @param winnerIds           list of winner user IDs
     * @param allEntrantIds       all entrant user IDs (unused currently)
     * @return list of tasks (possibly empty) representing notification operations
     */
    private List<Task<Void>> buildNotificationTasks(NotificationService notificationService, String eventId, List<String> winnerIds, List<String> allEntrantIds) {
        List<Task<Void>> tasks = new java.util.ArrayList<>();
        return tasks; // TODO: implement event name retrieval & notifications if required by spec
    }

    /**
     * Check if lottery has already been conducted for an event.
     *
     * @param eventId event identifier
     * @return Task resolving true if a result document already exists
     */
    public Task<Boolean> hasLotteryBeenConducted(@NonNull String eventId) {
        return db.collection(LOTTERY_RESULTS_COLL)
                .document(eventId)
                .get()
                .continueWith(task -> {
                    if (!task.isSuccessful()) return false;
                    DocumentSnapshot doc = task.getResult();
                    return doc != null && doc.exists();
                });
    }

    /**
     * Retrieve an existing lottery result if present.
     *
     * @param eventId event identifier
     * @return Task resolving with result or null if absent / failure
     */
    public Task<LotteryResult> getLotteryResult(@NonNull String eventId) {
        return db.collection(LOTTERY_RESULTS_COLL)
                .document(eventId)
                .get()
                .continueWith(task -> {
                    if (!task.isSuccessful() || task.getResult() == null) {
                        return null;
                    }
                    return task.getResult().toObject(LotteryResult.class);
                });
    }

    /**
     * Determine if a user appears in the winner set.
     *
     * @param eventId event identifier
     * @param userId  user identifier
     * @return Task resolving true if user is a winner
     */
    public Task<Boolean> isWinner(@NonNull String eventId, @NonNull String userId) {
        return getLotteryResult(eventId)
                .continueWith(task -> {
                    if (!task.isSuccessful() || task.getResult() == null) {
                        return false;
                    }
                    LotteryResult result = task.getResult();
                    return result.getWinnerIds() != null &&
                           result.getWinnerIds().contains(userId);
                });
    }

    /**
     * Persist the lottery result document.
     *
     * @param result result representation to store
     * @return Task resolving with the same result on success
     */
    private Task<LotteryResult> saveLotteryResult(LotteryResult result) {
        Map<String, Object> data = new HashMap<>();
        data.put("event_id", result.getEventId());
        data.put("conducted_at", result.getConductedAt());
        data.put("lottery_method", result.getLotteryMethod());
        data.put("total_entrants", result.getTotalEntrants());
        data.put("num_winners", result.getNumWinners());
        data.put("winner_ids", result.getWinnerIds());
        data.put("conducted_by", result.getConductedBy());

        return db.collection(LOTTERY_RESULTS_COLL)
                .document(result.getEventId())
                .set(data)
                .continueWith(task -> {
                    if (!task.isSuccessful()) {
                        throw task.getException();
                    }
                    return result;
                });
    }
}

package ca.team.originkickoff.services;

import androidx.annotation.NonNull;

import com.google.android.gms.tasks.Task;
import com.google.android.gms.tasks.Tasks;

import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import ca.team.originkickoff.models.LotteryMethod;
import ca.team.originkickoff.models.WaitingListEntry;

/**
 * Service for conducting fair lottery selection from waiting list entries.
 * Supports two methods:
 * 1. RANDOM: Pure random selection using SecureRandom
 * 2. EARLY_PRIORITY_RANDOM: Weighted selection favoring earlier entrants
 */
public class LotteryService {
    private final SecureRandom secureRandom;
    private final WaitingListService waitingListService;

    // Decay factor for early priority weighting (higher = more advantage to early entrants)
    // With 0.5, weight halves every normalized time unit
    private static final double EARLY_PRIORITY_DECAY = 0.5;

    public LotteryService() {
        this.secureRandom = new SecureRandom();
        this.waitingListService = new WaitingListService();
    }

    /**
     * Conduct a lottery draw for an event.
     *
     * @param eventId The event ID
     * @param method The lottery method to use
     * @param numWinners Number of winners to select
     * @return Task containing list of selected winner user IDs
     */
    public Task<List<String>> conductLottery(@NonNull String eventId,
                                              @NonNull LotteryMethod method,
                                              int numWinners) {
        if (numWinners <= 0) {
            return Tasks.forResult(new ArrayList<>());
        }

        return waitingListService.listActive(eventId)
                .continueWith(task -> {
                    if (!task.isSuccessful() || task.getResult() == null) {
                        throw new Exception("Failed to retrieve waiting list entries");
                    }

                    List<WaitingListEntry> entries = task.getResult();
                    if (entries.isEmpty()) {
                        return new ArrayList<>();
                    }

                    // Can't select more winners than available entrants
                    int actualWinners = Math.min(numWinners, entries.size());

                    switch (method) {
                        case EARLY_PRIORITY_RANDOM:
                            return selectEarlyPriorityRandom(entries, actualWinners);
                        case RANDOM:
                        default:
                            return selectPureRandom(entries, actualWinners);
                    }
                });
    }

    /**
     * Pure random selection - all entrants have equal probability.
     * Uses Fisher-Yates shuffle with SecureRandom for cryptographic security.
     *
     * @param entries List of waiting list entries
     * @param numWinners Number of winners to select
     * @return List of selected user IDs
     */
    private List<String> selectPureRandom(List<WaitingListEntry> entries, int numWinners) {
        // Create a copy to avoid modifying original list
        List<WaitingListEntry> shuffled = new ArrayList<>(entries);

        // Fisher-Yates shuffle using SecureRandom
        for (int i = shuffled.size() - 1; i > 0; i--) {
            int j = secureRandom.nextInt(i + 1);
            Collections.swap(shuffled, i, j);
        }

        // Take first numWinners entries
        List<String> winners = new ArrayList<>();
        for (int i = 0; i < numWinners && i < shuffled.size(); i++) {
            winners.add(shuffled.get(i).getUserId());
        }

        return winners;
    }

    /**
     * Early priority random selection - earlier entrants get higher weight.
     * Uses exponential decay: weight = e^(-decay * normalizedTime)
     * where normalizedTime ∈ [0, 1], 0 = earliest, 1 = latest
     *
     * Algorithm: Weighted reservoir sampling with exponential weights
     *
     * @param entries List of waiting list entries (assumed sorted by joinedAt ascending)
     * @param numWinners Number of winners to select
     * @return List of selected user IDs
     */
    private List<String> selectEarlyPriorityRandom(List<WaitingListEntry> entries, int numWinners) {
        if (entries.isEmpty()) {
            return new ArrayList<>();
        }

        // Calculate weights based on join time
        List<WeightedEntry> weightedEntries = new ArrayList<>();

        long earliestTime = entries.get(0).getJoinedAt().getSeconds();
        long latestTime = entries.get(entries.size() - 1).getJoinedAt().getSeconds();
        long timeRange = latestTime - earliestTime;

        for (WaitingListEntry entry : entries) {
            double normalizedTime;
            if (timeRange == 0) {
                // All joined at same time - equal weights
                normalizedTime = 0;
            } else {
                // Normalize to [0, 1] where 0 = earliest
                normalizedTime = (double) (entry.getJoinedAt().getSeconds() - earliestTime) / timeRange;
            }

            // Exponential decay weight: earlier = higher weight
            // e^(-decay * 0) = 1.0 (earliest)
            // e^(-decay * 1) ≈ 0.6 (latest, with decay=0.5)
            double weight = Math.exp(-EARLY_PRIORITY_DECAY * normalizedTime);

            weightedEntries.add(new WeightedEntry(entry.getUserId(), weight));
        }

        // Use weighted random sampling without replacement
        return weightedRandomSample(weightedEntries, numWinners);
    }

    /**
     * Weighted random sampling without replacement using the "Efraimidis-Spirakis" algorithm.
     * For each item, generate key = random^(1/weight), then select items with largest keys.
     * This is efficient and provably fair.
     *
     * @param weightedEntries List of entries with weights
     * @param numSamples Number of samples to draw
     * @return List of selected user IDs
     */
    private List<String> weightedRandomSample(List<WeightedEntry> weightedEntries, int numSamples) {
        List<ScoredEntry> scoredEntries = new ArrayList<>();

        for (WeightedEntry entry : weightedEntries) {
            // Generate uniform random [0, 1)
            double random = secureRandom.nextDouble();

            // Avoid log(0) by using a tiny minimum value
            if (random < 1e-10) random = 1e-10;

            // Calculate score: random^(1/weight) = exp(log(random) / weight)
            double score = Math.exp(Math.log(random) / entry.weight);

            scoredEntries.add(new ScoredEntry(entry.userId, score));
        }

        // Sort by score descending (highest scores win)
        Collections.sort(scoredEntries, (a, b) -> Double.compare(b.score, a.score));

        // Take top numSamples
        List<String> winners = new ArrayList<>();
        for (int i = 0; i < numSamples && i < scoredEntries.size(); i++) {
            winners.add(scoredEntries.get(i).userId);
        }

        return winners;
    }

    /**
     * Helper class for weighted entries
     */
    private static class WeightedEntry {
        final String userId;
        final double weight;

        WeightedEntry(String userId, double weight) {
            this.userId = userId;
            this.weight = weight;
        }
    }

    /**
     * Helper class for scored entries (used in weighted sampling)
     */
    private static class ScoredEntry {
        final String userId;
        final double score;

        ScoredEntry(String userId, double score) {
            this.userId = userId;
            this.score = score;
        }
    }
}

/*
 * Lottery selection service encapsulating algorithms for choosing winners.
 * Supports pure random and early-priority weighted random selection strategies.
 */
package ca.team.originkickoff.services;

import androidx.annotation.NonNull;

import com.google.android.gms.tasks.Task;
import com.google.android.gms.tasks.Tasks;

import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import ca.team.originkickoff.models.LotteryMethod;
import ca.team.originkickoff.models.WaitingListEntry;

/**
 * Provides algorithms to fairly select winners from waiting list entries based on
 * configured {@link LotteryMethod}. Implements pure random and weighted early priority selection.
 */
public class LotteryService {
    private final SecureRandom secureRandom;
    private final WaitingListService waitingListService;
    private static final double EARLY_PRIORITY_DECAY = 0.5;

    /**
     * Constructs a lottery service with a cryptographically strong random source.
     */
    public LotteryService() {
        this.secureRandom = new SecureRandom();
        this.waitingListService = new WaitingListService();
    }

    /**
     * Conduct a lottery draw for an event using the specified method.
     *
     * @param eventId    event identifier
     * @param method     selection method to apply
     * @param numWinners requested number of winners (clamped to entrant count)
     * @return Task resolving with list of winner user IDs
     */
    public Task<List<String>> conductLottery(@NonNull String eventId,
                                              @NonNull LotteryMethod method,
                                              int numWinners) {
        if (numWinners <= 0) {
            return Tasks.forResult(new ArrayList<>());
        }
        return waitingListService.listActive(eventId)
                .continueWith(task -> {
                    if (!task.isSuccessful() || task.getResult() == null) {
                        throw new Exception("Failed to retrieve waiting list entries");
                    }
                    List<WaitingListEntry> entries = task.getResult();
                    if (entries.isEmpty()) {
                        return new ArrayList<>();
                    }
                    int actualWinners = Math.min(numWinners, entries.size());
                    switch (method) {
                        case EARLY_PRIORITY_RANDOM:
                            return selectEarlyPriorityRandom(entries, actualWinners);
                        case RANDOM:
                        default:
                            return selectPureRandom(entries, actualWinners);
                    }
                });
    }

    /**
     * Pure random selection where all entrants have equal probability.
     * Implements Fisher-Yates shuffle for unbiased ordering.
     *
     * @param entries list of waiting list entries
     * @param numWinners number of winners to select
     * @return winner user IDs
     */
    private List<String> selectPureRandom(List<WaitingListEntry> entries, int numWinners) {
        List<WaitingListEntry> shuffled = new ArrayList<>(entries);
        for (int i = shuffled.size() - 1; i > 0; i--) {
            int j = secureRandom.nextInt(i + 1);
            Collections.swap(shuffled, i, j);
        }
        List<String> winners = new ArrayList<>();
        for (int i = 0; i < numWinners && i < shuffled.size(); i++) {
            winners.add(shuffled.get(i).getUserId());
        }
        return winners;
    }

    /**
     * Early priority selection favoring earlier entrants using exponential decay weighting.
     * Normalizes join times to [0,1] before computing decayed weights.
     *
     * @param entries sorted waiting list entries (ascending by joinedAt)
     * @param numWinners number of winners to select
     * @return winner user IDs
     */
    private List<String> selectEarlyPriorityRandom(List<WaitingListEntry> entries, int numWinners) {
        if (entries.isEmpty()) {
            return new ArrayList<>();
        }
        List<WeightedEntry> weightedEntries = new ArrayList<>();
        long earliestTime = entries.get(0).getJoinedAt().getSeconds();
        long latestTime = entries.get(entries.size() - 1).getJoinedAt().getSeconds();
        long timeRange = latestTime - earliestTime;
        for (WaitingListEntry entry : entries) {
            double normalizedTime = timeRange == 0 ? 0 : (double) (entry.getJoinedAt().getSeconds() - earliestTime) / timeRange;
            double weight = Math.exp(-EARLY_PRIORITY_DECAY * normalizedTime);
            weightedEntries.add(new WeightedEntry(entry.getUserId(), weight));
        }
        return weightedRandomSample(weightedEntries, numWinners);
    }

    /**
     * Weighted random sampling without replacement using Efraimidis-Spirakis algorithm.
     * Generates a score per entry and selects highest scores.
     *
     * @param weightedEntries entries with precomputed weights
     * @param numSamples number of samples to draw
     * @return selected user IDs
     */
    private List<String> weightedRandomSample(List<WeightedEntry> weightedEntries, int numSamples) {
        List<ScoredEntry> scoredEntries = new ArrayList<>();
        for (WeightedEntry entry : weightedEntries) {
            double random = secureRandom.nextDouble();
            if (random < 1e-10) random = 1e-10;
            double score = Math.exp(Math.log(random) / entry.weight);
            scoredEntries.add(new ScoredEntry(entry.userId, score));
        }
        Collections.sort(scoredEntries, (a, b) -> Double.compare(b.score, a.score));
        List<String> winners = new ArrayList<>();
        for (int i = 0; i < numSamples && i < scoredEntries.size(); i++) {
            winners.add(scoredEntries.get(i).userId);
        }
        return winners;
    }

    /**
     * Container for a weighted entrant.
     */
    private static class WeightedEntry {
        final String userId;
        final double weight;
        WeightedEntry(String userId, double weight) { this.userId = userId; this.weight = weight; }
    }

    /**
     * Container for a scored entrant during sampling.
     */
    private static class ScoredEntry {
        final String userId;
        final double score;
        ScoredEntry(String userId, double score) { this.userId = userId; this.score = score; }
    }
}

package ca.team.originkickoff.services;

import android.util.Log;

import androidx.annotation.NonNull;

import com.google.android.gms.tasks.Task;
import com.google.firebase.Timestamp;
import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.ListenerRegistration;
import com.google.firebase.firestore.DocumentSnapshot;
import com.google.firebase.firestore.Query;
import com.google.firebase.firestore.QuerySnapshot;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import ca.team.originkickoff.models.NotificationItem;

/**
 * Service for managing user notifications in Firestore.
 */
public class NotificationService {
    private static final String TAG = "NotificationService";
    private static final String NOTIFICATIONS_COLL = "notifications";

    private final FirebaseFirestore db = FirebaseFirestore.getInstance();

    /**
     * Get all notifications for a user, sorted by creation time (newest first).
     */
    public Task<List<NotificationItem>> getNotificationsForUser(@NonNull String userId) {
        Log.d(TAG, "Fetching notifications for userId: " + userId);

        // Try the ordered query first (requires composite index)
        return db.collection(NOTIFICATIONS_COLL)
                .whereEqualTo("userId", userId)
                .orderBy("createdAt", Query.Direction.DESCENDING)
                .get()
                .continueWithTask(task -> {
                    // If the query fails due to missing index, try without ordering
                    if (!task.isSuccessful() && task.getException() != null) {
                        String errorMsg = task.getException().getMessage();
                        Log.e(TAG, "Ordered query failed: " + errorMsg);

                        if (errorMsg != null && errorMsg.contains("index")) {
                            Log.w(TAG, "Composite index missing. Falling back to unordered query.");
                            Log.w(TAG, "Create the index in Firebase Console for better performance.");

                            // Fallback: Query without ordering (doesn't require composite index)
                            return db.collection(NOTIFICATIONS_COLL)
                                    .whereEqualTo("userId", userId)
                                    .get();
                        }
                    }
                    return task;
                })
                .continueWith(task -> {
                    List<NotificationItem> notifications = new ArrayList<>();
                    if (task.isSuccessful() && task.getResult() != null) {
                        QuerySnapshot snapshot = task.getResult();
                        Log.d(TAG, "Found " + snapshot.size() + " notifications");

                        for (com.google.firebase.firestore.DocumentSnapshot doc : snapshot.getDocuments()) {
                            try {
                                NotificationItem item = doc.toObject(NotificationItem.class);
                                if (item != null) {
                                    item.setId(doc.getId());
                                    notifications.add(item);
                                    Log.d(TAG, "Notification: " + item.getTitle() + " | Type: " + item.getType() + " | EventId: " + item.getEventId());
                                }
                            } catch (Exception e) {
                                Log.e(TAG, "Error parsing notification document: " + doc.getId(), e);
                            }
                        }

                        // Sort by createdAt manually if we used the fallback query
                        if (!notifications.isEmpty() && notifications.get(0).getCreatedAt() != null) {
                            Collections.sort(notifications, (a, b) -> {
                                if (a.getCreatedAt() == null) return 1;
                                if (b.getCreatedAt() == null) return -1;
                                return b.getCreatedAt().compareTo(a.getCreatedAt()); // Descending
                            });
                        }
                    } else if (task.getException() != null) {
                        Log.e(TAG, "Error fetching notifications", task.getException());
                    }

                    Log.d(TAG, "Returning " + notifications.size() + " notifications");
                    return notifications;
                });
    }

    /**
     * Real-time updates: listen for notifications for a user. Automatically sorts DESC by createdAt.
     */
    public ListenerRegistration listenNotificationsForUser(@NonNull String userId,
                                                            @NonNull java.util.function.Consumer<List<NotificationItem>> onUpdate,
                                                            @NonNull java.util.function.Consumer<Exception> onError) {
        // Use simple whereEqualTo; ordering with snapshot requires composite index; we'll sort client-side
        return db.collection(NOTIFICATIONS_COLL)
                .whereEqualTo("userId", userId)
                .addSnapshotListener((snap, err) -> {
                    if (err != null) {
                        Log.e(TAG, "Notification listener error", err);
                        onError.accept(err);
                        return;
                    }
                    List<NotificationItem> notifications = new ArrayList<>();
                    if (snap != null) {
                        for (DocumentSnapshot doc : snap.getDocuments()) {
                            try {
                                NotificationItem item = doc.toObject(NotificationItem.class);
                                if (item != null) {
                                    item.setId(doc.getId());
                                    notifications.add(item);
                                }
                            } catch (Exception ex) {
                                Log.e(TAG, "Failed to parse notification " + doc.getId(), ex);
                            }
                        }
                    }
                    // Client-side sort
                    Collections.sort(notifications, (a, b) -> {
                        if (a.getCreatedAt() == null && b.getCreatedAt() == null) return 0;
                        if (a.getCreatedAt() == null) return 1;
                        if (b.getCreatedAt() == null) return -1;
                        return b.getCreatedAt().compareTo(a.getCreatedAt());
                    });
                    onUpdate.accept(notifications);
                });
    }

    /**
     * Mark a notification as read.
     */
    public Task<Void> markAsRead(@NonNull String notificationId) {
        Map<String, Object> updates = new HashMap<>();
        updates.put("read", true);

        return db.collection(NOTIFICATIONS_COLL)
                .document(notificationId)
                .update(updates);
    }

    /**
     * Create a lottery result notification.
     */
    public Task<Void> createLotteryNotification(@NonNull String userId, @NonNull String eventId,
                                                 @NonNull String eventName, boolean isWinner) {
        String notificationId = db.collection(NOTIFICATIONS_COLL).document().getId();
        Map<String, Object> notification = new HashMap<>();
        notification.put("userId", userId);
        notification.put("eventId", eventId);
        notification.put("type", "result");
        notification.put("read", false);
        notification.put("createdAt", Timestamp.now());

        if (isWinner) {
            notification.put("title", " Lottery Result - You Won!");
            notification.put("message", "Congratulations! You were selected in the lottery for " + eventName);
        } else {
            notification.put("title", "Lottery Result");
            notification.put("message", "Unfortunately, you were not selected in the lottery for " + eventName);
        }

        return db.collection(NOTIFICATIONS_COLL)
                .document(notificationId)
                .set(notification);
    }
}

/*
 * Firestore notification management service.
 * Retrieves, listens to, creates, and updates user notification documents.
 */
package ca.team.originkickoff.services;

import android.util.Log;

import androidx.annotation.NonNull;

import com.google.android.gms.tasks.Task;
import com.google.firebase.Timestamp;
import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.ListenerRegistration;
import com.google.firebase.firestore.DocumentSnapshot;
import com.google.firebase.firestore.Query;
import com.google.firebase.firestore.QuerySnapshot;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import ca.team.originkickoff.models.NotificationItem;

/**
 * Service for managing user notifications stored in Firestore.
 * Provides list retrieval (with index fallback), real‑time listening, mutation, and creation helpers.
 */
public class NotificationService {
    private static final String TAG = "NotificationService";
    private static final String NOTIFICATIONS_COLL = "notifications";

    private final FirebaseFirestore db = FirebaseFirestore.getInstance();

    /**
     * Get all notifications for a user ordered by creation time descending.
     * Falls back to client‑side sorting if a composite index is missing.
     *
     * @param userId Firestore user identifier
     * @return Task resolving with a list (possibly empty) of notifications
     */
    public Task<List<NotificationItem>> getNotificationsForUser(@NonNull String userId) {
        Log.d(TAG, "Fetching notifications for userId: " + userId);

        // Try the ordered query first (requires composite index)
        return db.collection(NOTIFICATIONS_COLL)
                .whereEqualTo("userId", userId)
                .orderBy("createdAt", Query.Direction.DESCENDING)
                .get()
                .continueWithTask(task -> {
                    // If the query fails due to missing index, try without ordering
                    if (!task.isSuccessful() && task.getException() != null) {
                        String errorMsg = task.getException().getMessage();
                        Log.e(TAG, "Ordered query failed: " + errorMsg);

                        if (errorMsg != null && errorMsg.contains("index")) {
                            Log.w(TAG, "Composite index missing. Falling back to unordered query.");
                            Log.w(TAG, "Create the index in Firebase Console for better performance.");

                            // Fallback: Query without ordering (doesn't require composite index)
                            return db.collection(NOTIFICATIONS_COLL)
                                    .whereEqualTo("userId", userId)
                                    .get();
                        }
                    }
                    return task;
                })
                .continueWith(task -> {
                    List<NotificationItem> notifications = new ArrayList<>();
                    if (task.isSuccessful() && task.getResult() != null) {
                        QuerySnapshot snapshot = task.getResult();
                        Log.d(TAG, "Found " + snapshot.size() + " notifications");

                        for (com.google.firebase.firestore.DocumentSnapshot doc : snapshot.getDocuments()) {
                            try {
                                NotificationItem item = doc.toObject(NotificationItem.class);
                                if (item != null) {
                                    item.setId(doc.getId());
                                    notifications.add(item);
                                    Log.d(TAG, "Notification: " + item.getTitle() + " | Type: " + item.getType() + " | EventId: " + item.getEventId());
                                }
                            } catch (Exception e) {
                                Log.e(TAG, "Error parsing notification document: " + doc.getId(), e);
                            }
                        }

                        // Sort by createdAt manually if we used the fallback query
                        if (!notifications.isEmpty() && notifications.get(0).getCreatedAt() != null) {
                            Collections.sort(notifications, (a, b) -> {
                                if (a.getCreatedAt() == null) return 1;
                                if (b.getCreatedAt() == null) return -1;
                                return b.getCreatedAt().compareTo(a.getCreatedAt()); // Descending
                            });
                        }
                    } else if (task.getException() != null) {
                        Log.e(TAG, "Error fetching notifications", task.getException());
                    }

                    Log.d(TAG, "Returning " + notifications.size() + " notifications");
                    return notifications;
                });
    }

    /**
     * Attach a real‑time listener for notifications belonging to a user.
     * Results are client‑side sorted descending by createdAt.
     *
     * @param userId   user identifier
     * @param onUpdate consumer invoked with latest list of notifications
     * @param onError  consumer invoked on listener error
     * @return Firestore listener registration (caller should remove when no longer needed)
     */
    public ListenerRegistration listenNotificationsForUser(@NonNull String userId,
                                                            @NonNull java.util.function.Consumer<List<NotificationItem>> onUpdate,
                                                            @NonNull java.util.function.Consumer<Exception> onError) {
        // Use simple whereEqualTo; ordering with snapshot requires composite index; we'll sort client-side
        return db.collection(NOTIFICATIONS_COLL)
                .whereEqualTo("userId", userId)
                .addSnapshotListener((snap, err) -> {
                    if (err != null) {
                        Log.e(TAG, "Notification listener error", err);
                        onError.accept(err);
                        return;
                    }
                    List<NotificationItem> notifications = new ArrayList<>();
                    if (snap != null) {
                        for (DocumentSnapshot doc : snap.getDocuments()) {
                            try {
                                NotificationItem item = doc.toObject(NotificationItem.class);
                                if (item != null) {
                                    item.setId(doc.getId());
                                    notifications.add(item);
                                }
                            } catch (Exception ex) {
                                Log.e(TAG, "Failed to parse notification " + doc.getId(), ex);
                            }
                        }
                    }
                    // Client-side sort
                    Collections.sort(notifications, (a, b) -> {
                        if (a.getCreatedAt() == null && b.getCreatedAt() == null) return 0;
                        if (a.getCreatedAt() == null) return 1;
                        if (b.getCreatedAt() == null) return -1;
                        return b.getCreatedAt().compareTo(a.getCreatedAt());
                    });
                    onUpdate.accept(notifications);
                });
    }

    /**
     * Mark a notification document as read.
     *
     * @param notificationId document ID of the notification
     * @return Task resolving when update completes
     */
    public Task<Void> markAsRead(@NonNull String notificationId) {
        Map<String, Object> updates = new HashMap<>();
        updates.put("read", true);

        return db.collection(NOTIFICATIONS_COLL)
                .document(notificationId)
                .update(updates);
    }

    /**
     * Create and persist a lottery result notification for a user.
     *
     * @param userId    target user identifier
     * @param eventId   related event identifier
     * @param eventName human‑readable event name for message composition
     * @param isWinner  whether the user won the lottery
     * @return Task resolving when notification is stored
     */
    public Task<Void> createLotteryNotification(@NonNull String userId, @NonNull String eventId,
                                                 @NonNull String eventName, boolean isWinner) {
        String notificationId = db.collection(NOTIFICATIONS_COLL).document().getId();
        Map<String, Object> notification = new HashMap<>();
        notification.put("userId", userId);
        notification.put("eventId", eventId);
        notification.put("type", "result");
        notification.put("read", false);
        notification.put("createdAt", Timestamp.now());

        if (isWinner) {
            notification.put("title", " Lottery Result - You Won!");
            notification.put("message", "Congratulations! You were selected in the lottery for " + eventName);
        } else {
            notification.put("title", "Lottery Result");
            notification.put("message", "Unfortunately, you were not selected in the lottery for " + eventName);
        }

        return db.collection(NOTIFICATIONS_COLL)
                .document(notificationId)
                .set(notification);
    }
}

package ca.team.originkickoff.services;

import androidx.annotation.NonNull;

import com.google.android.gms.tasks.Task;
import com.google.firebase.Timestamp;
import com.google.firebase.firestore.DocumentReference;
import com.google.firebase.firestore.DocumentSnapshot;
import com.google.firebase.firestore.FieldValue;
import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.Query;
import com.google.firebase.firestore.QuerySnapshot;
import com.google.firebase.firestore.Transaction;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import ca.team.originkickoff.models.WaitingListEntry;

public class WaitingListService {
    private static final String EVENTS_COLL = "events";
    private static final String WAITLIST_COLL = "waiting_list_entries"; // mirrors RDBMS table name

    private final FirebaseFirestore db = FirebaseFirestore.getInstance();

    public DocumentReference waitlistDoc(String eventId, String userId) {
        return db.collection(WAITLIST_COLL).document(WaitingListEntry.docId(eventId, userId));
    }

    public Task<Boolean> isOnWaitlist(@NonNull String eventId, @NonNull String userId) {
        return waitlistDoc(eventId, userId)
                .get()
                .continueWith(task -> {
                    if (!task.isSuccessful()) return false;
                    DocumentSnapshot snap = task.getResult();
                    return snap != null && snap.exists() && "active".equals(snap.getString("state"));
                });
    }

    // Returns true if state changed to active (i.e., we actually joined now)
    public Task<Boolean> join(@NonNull String eventId, @NonNull String userId, boolean locationConsent,
                              Double lat, Double lon, Integer precisionMeters, String source) {
        DocumentReference wlRef = waitlistDoc(eventId, userId);
        DocumentReference eventRef = db.collection(EVENTS_COLL).document(eventId);

        return db.runTransaction(transaction -> {
            DocumentSnapshot snap = transaction.get(wlRef);
            boolean wasActive = snap.exists() && "active".equals(snap.getString("state"));
            if (wasActive) {
                return false; // no-op
            }

            // Enforce optional waitlist limit
            DocumentSnapshot eventSnap = transaction.get(eventRef);
            Long waitlistCount = eventSnap.getLong("waitlistCount");
            Boolean limitWaitlist = eventSnap.getBoolean("limitWaitlist");
            Long waitlistLimit = eventSnap.getLong("waitlistLimit");
            long currentCount = waitlistCount != null ? waitlistCount : 0L;
            boolean isLimited = limitWaitlist != null && limitWaitlist;
            long limit = waitlistLimit != null ? waitlistLimit : Long.MAX_VALUE;
            if (isLimited && currentCount >= limit) {
                throw new IllegalStateException("Waitlist is full for this event");
            }

            Map<String, Object> data = new HashMap<>();
            data.put("event_id", eventId);
            data.put("user_id", userId);
            data.put("joined_at", Timestamp.now());
            data.put("source", source == null ? "list" : source);
            data.put("state", "active");
            if (lat != null) data.put("lat", lat);
            if (lon != null) data.put("lon", lon);
            if (precisionMeters != null) data.put("precision_m", precisionMeters);
            data.put("location_consent", locationConsent);

            transaction.set(wlRef, data);
            transaction.update(eventRef, "waitlistCount", FieldValue.increment(1));
            return true; // state changed
        });
    }

    // Returns true if state changed to left (i.e., we actually left now)
    public Task<Boolean> leave(@NonNull String eventId, @NonNull String userId) {
        DocumentReference wlRef = waitlistDoc(eventId, userId);
        DocumentReference eventRef = db.collection(EVENTS_COLL).document(eventId);

        return db.runTransaction((Transaction.Function<Boolean>) transaction -> {
            DocumentSnapshot snap = transaction.get(wlRef);
            boolean wasActive = snap.exists() && "active".equals(snap.getString("state"));
            if (!wasActive) {
                return false; // nothing to do
            }
            transaction.update(wlRef, "state", "left");
            transaction.update(eventRef, "waitlistCount", FieldValue.increment(-1));
            return true;
        });
    }

    public Task<Integer> countActive(@NonNull String eventId) {
        Query q = db.collection(WAITLIST_COLL)
                .whereEqualTo("event_id", eventId)
                .whereEqualTo("state", "active");
        return q.get().continueWith(t -> t.isSuccessful() ? t.getResult().size() : 0);
    }

    public Task<List<String>> getAllActiveUserIds(@NonNull String eventId) {
        Query q = db.collection(WAITLIST_COLL)
                .whereEqualTo("event_id", eventId)
                .whereEqualTo("state", "active");

        return q.get().continueWith(task -> {
            if (!task.isSuccessful()) {
                throw task.getException();
            }
            List<String> userIds = new ArrayList<>();
            QuerySnapshot snaps = task.getResult();
            if (snaps != null) {
                for (DocumentSnapshot s : snaps.getDocuments()) {
                    String userId = s.getString("user_id");
                    if (userId != null) {
                        userIds.add(userId);
                    }
                }
            }
            return userIds;
        });
    }

    public Task<List<WaitingListEntry>> listActive(@NonNull String eventId) {
        Query q = db.collection(WAITLIST_COLL)
                .whereEqualTo("event_id", eventId)
                .whereEqualTo("state", "active");

        return q.get().continueWith(task -> {
            if (!task.isSuccessful()) {
                // Propagate failure so callers can surface an error
                throw task.getException();
            }
            List<WaitingListEntry> out = new ArrayList<>();
            QuerySnapshot snaps = task.getResult();
            if (snaps != null) {
                for (DocumentSnapshot s : snaps.getDocuments()) {
                    WaitingListEntry e = s.toObject(WaitingListEntry.class);
                    if (e != null) out.add(e);
                }
            }
            // Sort client-side by joined_at ascending to avoid composite index need
            Collections.sort(out, new Comparator<WaitingListEntry>() {
                @Override
                public int compare(WaitingListEntry a, WaitingListEntry b) {
                    if (a.getJoinedAt() == null && b.getJoinedAt() == null) return 0;
                    if (a.getJoinedAt() == null) return 1;
                    if (b.getJoinedAt() == null) return -1;
                    long da = a.getJoinedAt().getSeconds();
                    long db = b.getJoinedAt().getSeconds();
                    return Long.compare(da, db);
                }
            });
            return out;
        });
    }
}

/*
 * Service for managing event waiting list entries and related counts in Firestore.
 * Encapsulates join/leave flows, queries, and basic client-side ordering.
 */
package ca.team.originkickoff.services;

import androidx.annotation.NonNull;

import com.google.android.gms.tasks.Task;
import com.google.firebase.Timestamp;
import com.google.firebase.firestore.DocumentReference;
import com.google.firebase.firestore.DocumentSnapshot;
import com.google.firebase.firestore.FieldValue;
import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.Query;
import com.google.firebase.firestore.QuerySnapshot;
import com.google.firebase.firestore.Transaction;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import ca.team.originkickoff.models.WaitingListEntry;

/**
 * Firestore-backed operations for the waiting list lifecycle and queries.
 */
public class WaitingListService {
    private static final String EVENTS_COLL = "events";
    private static final String WAITLIST_COLL = "waiting_list_entries"; // mirrors RDBMS table name

    private final FirebaseFirestore db = FirebaseFirestore.getInstance();

    /**
     * Reference helper for a user's waitlist document for a given event.
     *
     * @param eventId event identifier
     * @param userId  user identifier
     * @return document reference in the waiting list collection
     */
    public DocumentReference waitlistDoc(String eventId, String userId) {
        return db.collection(WAITLIST_COLL).document(WaitingListEntry.docId(eventId, userId));
    }

    /**
     * Checks whether the user currently has an active waitlist entry for an event.
     *
     * @param eventId event identifier
     * @param userId  user identifier
     * @return Task resolving true if active, else false
     */
    public Task<Boolean> isOnWaitlist(@NonNull String eventId, @NonNull String userId) {
        return waitlistDoc(eventId, userId)
                .get()
                .continueWith(task -> {
                    if (!task.isSuccessful()) return false;
                    DocumentSnapshot snap = task.getResult();
                    return snap != null && snap.exists() && "active".equals(snap.getString("state"));
                });
    }

    /**
     * Joins the user to the event's waitlist if not already active.
     * Increments the event waitlist counter within a transaction.
     *
     * @param eventId          event identifier
     * @param userId           user identifier
     * @param locationConsent  whether the user consented to share location
     * @param lat              latitude (nullable)
     * @param lon              longitude (nullable)
     * @param precisionMeters  location precision in meters (nullable)
     * @param source           origin of the join action (e.g., list/qr)
     * @return Task resolving true if state changed from not-active to active
     */
    public Task<Boolean> join(@NonNull String eventId, @NonNull String userId, boolean locationConsent,
                              Double lat, Double lon, Integer precisionMeters, String source) {
        DocumentReference wlRef = waitlistDoc(eventId, userId);
        DocumentReference eventRef = db.collection(EVENTS_COLL).document(eventId);

        return db.runTransaction(transaction -> {
            DocumentSnapshot snap = transaction.get(wlRef);
            boolean wasActive = snap.exists() && "active".equals(snap.getString("state"));
            if (wasActive) {
                return false;
            }

            // Enforce optional waitlist limit
            DocumentSnapshot eventSnap = transaction.get(eventRef);
            Long waitlistCount = eventSnap.getLong("waitlistCount");
            Boolean limitWaitlist = eventSnap.getBoolean("limitWaitlist");
            Long waitlistLimit = eventSnap.getLong("waitlistLimit");
            long currentCount = waitlistCount != null ? waitlistCount : 0L;
            boolean isLimited = limitWaitlist != null && limitWaitlist;
            long limit = waitlistLimit != null ? waitlistLimit : Long.MAX_VALUE;
            if (isLimited && currentCount >= limit) {
                throw new IllegalStateException("Waitlist is full for this event");
            }

            Map<String, Object> data = new HashMap<>();
            data.put("event_id", eventId);
            data.put("user_id", userId);
            data.put("joined_at", Timestamp.now());
            data.put("source", source == null ? "list" : source);
            data.put("state", "active");
            if (lat != null) data.put("lat", lat);
            if (lon != null) data.put("lon", lon);
            if (precisionMeters != null) data.put("precision_m", precisionMeters);
            data.put("location_consent", locationConsent);

            transaction.set(wlRef, data);
            transaction.update(eventRef, "waitlistCount", FieldValue.increment(1));
            return true; // state changed
        });
    }

    /**
     * Leaves the waitlist if currently active and decrements the event counter.
     *
     * @param eventId event identifier
     * @param userId  user identifier
     * @return Task resolving true if state changed to left
     */
    public Task<Boolean> leave(@NonNull String eventId, @NonNull String userId) {
        DocumentReference wlRef = waitlistDoc(eventId, userId);
        DocumentReference eventRef = db.collection(EVENTS_COLL).document(eventId);

        return db.runTransaction((Transaction.Function<Boolean>) transaction -> {
            DocumentSnapshot snap = transaction.get(wlRef);
            boolean wasActive = snap.exists() && "active".equals(snap.getString("state"));
            if (!wasActive) {
                return false; // nothing to do
            }
            transaction.update(wlRef, "state", "left");
            transaction.update(eventRef, "waitlistCount", FieldValue.increment(-1));
            return true;
        });
    }

    /**
     * Counts active waitlist entries for an event.
     *
     * @param eventId event identifier
     * @return Task resolving with the number of active entries
     */
    public Task<Integer> countActive(@NonNull String eventId) {
        Query q = db.collection(WAITLIST_COLL)
                .whereEqualTo("event_id", eventId)
                .whereEqualTo("state", "active");
        return q.get().continueWith(t -> t.isSuccessful() ? t.getResult().size() : 0);
    }

    /**
     * Retrieves user IDs for all active waitlist entries for an event.
     *
     * @param eventId event identifier
     * @return Task resolving with a list of user IDs
     */
    public Task<List<String>> getAllActiveUserIds(@NonNull String eventId) {
        Query q = db.collection(WAITLIST_COLL)
                .whereEqualTo("event_id", eventId)
                .whereEqualTo("state", "active");

        return q.get().continueWith(task -> {
            if (!task.isSuccessful()) {
                throw task.getException();
            }
            List<String> userIds = new ArrayList<>();
            QuerySnapshot snaps = task.getResult();
            if (snaps != null) {
                for (DocumentSnapshot s : snaps.getDocuments()) {
                    String userId = s.getString("user_id");
                    if (userId != null) {
                        userIds.add(userId);
                    }
                }
            }
            return userIds;
        });
    }

    /**
     * Lists active waiting list entries for an event, client-side sorted by join time ascending.
     *
     * @param eventId event identifier
     * @return Task resolving with ordered entries
     */
    public Task<List<WaitingListEntry>> listActive(@NonNull String eventId) {
        Query q = db.collection(WAITLIST_COLL)
                .whereEqualTo("event_id", eventId)
                .whereEqualTo("state", "active");

        return q.get().continueWith(task -> {
            if (!task.isSuccessful()) {
                // Propagate failure so callers can surface an error
                throw task.getException();
            }
            List<WaitingListEntry> out = new ArrayList<>();
            QuerySnapshot snaps = task.getResult();
            if (snaps != null) {
                for (DocumentSnapshot s : snaps.getDocuments()) {
                    WaitingListEntry e = s.toObject(WaitingListEntry.class);
                    if (e != null) out.add(e);
                }
            }
            // Sort client-side by joined_at ascending to avoid composite index need
            Collections.sort(out, new Comparator<WaitingListEntry>() {
                @Override
                public int compare(WaitingListEntry a, WaitingListEntry b) {
                    if (a.getJoinedAt() == null && b.getJoinedAt() == null) return 0;
                    if (a.getJoinedAt() == null) return 1;
                    if (b.getJoinedAt() == null) return -1;
                    long da = a.getJoinedAt().getSeconds();
                    long db = b.getJoinedAt().getSeconds();
                    return Long.compare(da, db);
                }
            });
            return out;
        });
    }
}

package ca.team.originkickoff.ui.fragments;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.os.Bundle;
import android.util.Base64;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ImageView;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;

import com.bumptech.glide.Glide;

import java.text.SimpleDateFormat;
import java.util.Locale;

import ca.team.originkickoff.R;
import ca.team.originkickoff.models.Event;
import ca.team.originkickoff.services.FirebaseEventService;

public class EventDetailFragment extends Fragment {
    private static final String ARG_EVENT_ID = "event_id";
    private String eventId;

    private ImageView detailEventPoster;
    private TextView detailEventName;
    private TextView detailOrganizerName;
    private TextView detailEventDate;
    private TextView detailEventLocation;
    private TextView detailEventPrice;
    private TextView detailCapacityInfo;
    private TextView detailWaitlistInfo;
    private TextView detailRegistrationPeriod;
    private TextView detailEventDescription;

    private FirebaseEventService firebaseEventService;

    public static EventDetailFragment newInstance(String eventId) {
        EventDetailFragment fragment = new EventDetailFragment();
        Bundle args = new Bundle();
        args.putString(ARG_EVENT_ID, eventId);
        fragment.setArguments(args);
        return fragment;
    }

    @Override
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        if (getArguments() != null) {
            eventId = getArguments().getString(ARG_EVENT_ID);
        }
    }

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_event_detail, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        initializeViews(view);
        firebaseEventService = new FirebaseEventService();
        loadEventDetails();
    }

    private void initializeViews(View view) {
        detailEventPoster = view.findViewById(R.id.detailEventPoster);
        detailEventName = view.findViewById(R.id.detailEventName);
        detailOrganizerName = view.findViewById(R.id.detailOrganizerName);
        detailEventDate = view.findViewById(R.id.detailEventDate);
        detailEventLocation = view.findViewById(R.id.detailEventLocation);
        detailEventPrice = view.findViewById(R.id.detailEventPrice);
        detailCapacityInfo = view.findViewById(R.id.detailCapacityInfo);
        detailWaitlistInfo = view.findViewById(R.id.detailWaitlistInfo);
        detailRegistrationPeriod = view.findViewById(R.id.detailRegistrationPeriod);
        detailEventDescription = view.findViewById(R.id.detailEventDescription);
    }

    private void loadEventDetails() {
        firebaseEventService.getEventById(eventId, new FirebaseEventService.SingleEventCallback() {
            @Override
            public void onSuccess(Event event) {
                displayEventDetails(event);
            }

            @Override
            public void onError(String errorMessage) {
                Toast.makeText(getContext(), "Error loading event: " + errorMessage,
                        Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void displayEventDetails(Event event) {
        SimpleDateFormat dateTimeFormat = new SimpleDateFormat("MMM dd, yyyy hh:mm a", Locale.getDefault());

        detailEventName.setText(event.getName());
        detailOrganizerName.setText(event.getOrganizerName());
        detailEventDescription.setText(event.getDescription());

        // Date and Time
        if (event.getEventDate() != null) {
            detailEventDate.setText(dateTimeFormat.format(event.getEventDate()));
        }

        // Location
        detailEventLocation.setText(event.getLocation());

        // Price
        if (event.getPrice() > 0) {
            detailEventPrice.setText(String.format(Locale.getDefault(), "$%.2f", event.getPrice()));
        } else {
            detailEventPrice.setText(R.string.free_label);
        }

        // Capacity Info
        int availableSpots = event.getCapacity() - event.getWaitlistCount();
        detailCapacityInfo.setText(String.format(Locale.getDefault(),
                "Capacity: %d participants", event.getCapacity()));

        // Waitlist Info
        detailWaitlistInfo.setText(String.format(Locale.getDefault(),
                "%d on waitlist • %d spots available",
                event.getWaitlistCount(), availableSpots));

        // Registration Period
        if (event.getRegistrationStartTime() != null && event.getRegistrationEndTime() != null) {
            String registrationPeriod = String.format(Locale.getDefault(),
                    "Opens: %s\nCloses: %s",
                    dateTimeFormat.format(event.getRegistrationStartTime()),
                    dateTimeFormat.format(event.getRegistrationEndTime()));
            detailRegistrationPeriod.setText(registrationPeriod);
        }

        // Poster Image preference: Base64 first, then URL fallback
        boolean loadedPoster = false;
        if (event.getPosterBase64() != null && !event.getPosterBase64().isEmpty()) {
            try {
                byte[] decoded = Base64.decode(event.getPosterBase64(), Base64.DEFAULT);
                Bitmap bmp = BitmapFactory.decodeByteArray(decoded, 0, decoded.length);
                if (bmp != null) {
                    detailEventPoster.setImageBitmap(bmp);
                    loadedPoster = true;
                }
            } catch (Exception ignored) { }
        }
        if (!loadedPoster) {
            if (event.getPosterUrl() != null && !event.getPosterUrl().isEmpty()) {
                Glide.with(this)
                        .load(event.getPosterUrl())
                        .placeholder(R.drawable.ic_launcher_background)
                        .error(R.drawable.ic_launcher_background)
                        .into(detailEventPoster);
            } else {
                detailEventPoster.setImageResource(R.drawable.ic_launcher_background);
            }
        }
    }
}

