                        .load(event.getPosterUrl())
                        .placeholder(R.drawable.ic_launcher_background)
                        .error(R.drawable.ic_launcher_background)
                        .into(detailEventPoster);
            } else {
                detailEventPoster.setImageResource(R.drawable.ic_launcher_background);
            }
        }
    }
}

package ca.team.originkickoff.ui.fragments;

import android.content.Intent;
import android.os.Bundle;
import android.text.Editable;
import android.text.TextWatcher;
import android.util.Log;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.EditText;
import android.widget.ImageButton;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.core.content.ContextCompat;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;
import androidx.swiperefreshlayout.widget.SwipeRefreshLayout;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import ca.team.originkickoff.R;
import ca.team.originkickoff.CreateEventActivity;
import ca.team.originkickoff.adapters.EventAdapter;
import ca.team.originkickoff.models.Event;
import ca.team.originkickoff.services.FirebaseEventService;

public class EventListFragment extends Fragment implements EventAdapter.OnEventClickListener {
    private static final String TAG = "EventListFragment";
    private RecyclerView eventsRecyclerView;
    private SwipeRefreshLayout swipeRefreshLayout;
    private LinearLayout emptyState;
    private LinearLayout loadingState;
    private EditText searchInput;
    private ImageButton filterButton;

    private EventAdapter adapter;
    private FirebaseEventService firebaseEventService;
    private final List<Event> allEvents = new ArrayList<>();
    private final List<Event> filteredEvents = new ArrayList<>();

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_event_list, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        initializeViews(view);
        setupRecyclerView();
        setupSwipeRefresh();
        setupSearchAndFilter();

        // Initialize the add button (in the Activity layout) and set click to open CreateEventActivity
        try {
            ImageView ivAddEvent = requireActivity().findViewById(R.id.ivAddEvent);
            if (ivAddEvent != null) {
                ivAddEvent.setOnClickListener(v -> {
                    Log.d(TAG, "ivAddEvent clicked - launching CreateEventActivity");
                    Intent i = new Intent(requireActivity(), CreateEventActivity.class);
                    startActivity(i);
                });
            }
        } catch (Exception e) {
            Log.w(TAG, "Could not bind ivAddEvent: " + e.getMessage());
        }

        firebaseEventService = new FirebaseEventService();
        loadEvents();
    }

    private void initializeViews(View view) {
        eventsRecyclerView = view.findViewById(R.id.eventsRecyclerView);
        swipeRefreshLayout = view.findViewById(R.id.swipeRefreshLayout);
        emptyState = view.findViewById(R.id.emptyState);
        loadingState = view.findViewById(R.id.loadingState);
        searchInput = view.findViewById(R.id.searchInput);
        filterButton = view.findViewById(R.id.filterButton);
    }

    private void setupRecyclerView() {
        adapter = new EventAdapter(filteredEvents, this);
        eventsRecyclerView.setLayoutManager(new LinearLayoutManager(getContext()));
        eventsRecyclerView.setAdapter(adapter);
    }

    private void setupSwipeRefresh() {
        swipeRefreshLayout.setOnRefreshListener(this::loadEvents);
        swipeRefreshLayout.setColorSchemeColors(ContextCompat.getColor(requireContext(), R.color.teal_700));
    }

    private void setupSearchAndFilter() {
        searchInput.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {
            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                filterEvents(s.toString());
            }

            @Override
            public void afterTextChanged(Editable s) {
            }
        });

        filterButton.setOnClickListener(v -> {
            // TODO: Implement advanced filtering (by date, price, location, etc.)
            Toast.makeText(getContext(), "Filter feature coming soon", Toast.LENGTH_SHORT).show();
        });
    }

    private void loadEvents() {
        Log.d(TAG, "loadEvents() called");
        showLoadingState(true);

        // Changed to getAllEvents to fetch all events from the database
        firebaseEventService.getAllEvents(new FirebaseEventService.EventsCallback() {
            @Override
            public void onSuccess(List<Event> events) {
                Log.d(TAG, "onSuccess called with " + events.size() + " events");
                allEvents.clear();
                allEvents.addAll(events);
                filteredEvents.clear();
                filteredEvents.addAll(events);
                Log.d(TAG, "Updated adapter with " + filteredEvents.size() + " events");
                adapter.updateEvents(filteredEvents);
                updateUIState();
                swipeRefreshLayout.setRefreshing(false);
                showLoadingState(false);

                if (events.isEmpty()) {
                    Toast.makeText(getContext(), "No events found", Toast.LENGTH_SHORT).show();
                } else {
                    Toast.makeText(getContext(), "Loaded " + events.size() + " events", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onError(String errorMessage) {
                Log.e(TAG, "onError called: " + errorMessage);
                swipeRefreshLayout.setRefreshing(false);
                showLoadingState(false);
                Toast.makeText(getContext(), "Error loading events: " + errorMessage,
                        Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void filterEvents(String query) {
        if (query.isEmpty()) {
            filteredEvents.clear();
            filteredEvents.addAll(allEvents);
        } else {
            String queryLower = query.toLowerCase();
            filteredEvents.clear();
            filteredEvents.addAll(
                    allEvents.stream()
                            .filter(event -> event.getName().toLowerCase().contains(queryLower) ||
                                    event.getDescription().toLowerCase().contains(queryLower) ||
                                    event.getLocation().toLowerCase().contains(queryLower) ||
                                    event.getOrganizerName().toLowerCase().contains(queryLower))
                            .collect(Collectors.toList())
            );
        }
        adapter.updateEvents(filteredEvents);
        updateUIState();
    }

    private void updateUIState() {
        if (filteredEvents.isEmpty()) {
            emptyState.setVisibility(View.VISIBLE);
            eventsRecyclerView.setVisibility(View.GONE);
        } else {
            emptyState.setVisibility(View.GONE);
            eventsRecyclerView.setVisibility(View.VISIBLE);
        }
    }

    private void showLoadingState(boolean isLoading) {
        if (isLoading && filteredEvents.isEmpty()) {
            loadingState.setVisibility(View.VISIBLE);
            eventsRecyclerView.setVisibility(View.GONE);
            emptyState.setVisibility(View.GONE);
        } else {
            loadingState.setVisibility(View.GONE);
        }
    }

    @Override
    public void onEventClick(Event event) {
        // Navigate to event detail fragment
        EventDetailFragment detailFragment = EventDetailFragment.newInstance(event.getId());
        getParentFragmentManager().beginTransaction()
                .replace(R.id.main, detailFragment)
                .addToBackStack(null)
                .commit();
    }
}

/*
 * Displays the list of events with search and pull-to-refresh capabilities.
 * Bridges Firestore-backed data to a RecyclerView via EventAdapter.
 */
package ca.team.originkickoff.ui.fragments;

import android.content.Intent;
import android.os.Bundle;
import android.text.Editable;
import android.text.TextWatcher;
import android.util.Log;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.EditText;
import android.widget.ImageButton;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.core.content.ContextCompat;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;
import androidx.swiperefreshlayout.widget.SwipeRefreshLayout;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import ca.team.originkickoff.R;
import ca.team.originkickoff.CreateEventActivity;
import ca.team.originkickoff.adapters.EventAdapter;
import ca.team.originkickoff.models.Event;
import ca.team.originkickoff.services.FirebaseEventService;

/**
 * Fragment that shows all events and supports searching/filtering and manual refresh.
 */
public class EventListFragment extends Fragment implements EventAdapter.OnEventClickListener {
    private static final String TAG = "EventListFragment";
    private RecyclerView eventsRecyclerView;
    private SwipeRefreshLayout swipeRefreshLayout;
    private LinearLayout emptyState;
    private LinearLayout loadingState;
    private EditText searchInput;
    private ImageButton filterButton;

    private EventAdapter adapter;
    private FirebaseEventService firebaseEventService;
    private final List<Event> allEvents = new ArrayList<>();
    private final List<Event> filteredEvents = new ArrayList<>();

    /**
     * Inflates the fragment layout.
     *
     * @param inflater  layout inflater
     * @param container parent container
     * @param savedInstanceState previous state bundle
     * @return inflated view for this fragment
     */
    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_event_list, container, false);
    }

    /**
     * Initializes views, sets up UI components, and triggers initial data load.
     *
     * @param view               root view
     * @param savedInstanceState previous state bundle
     */
    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        initializeViews(view);
        setupRecyclerView();
        setupSwipeRefresh();
        setupSearchAndFilter();

        // Initialize the add button (in the Activity layout) and set click to open CreateEventActivity
        try {
            ImageView ivAddEvent = requireActivity().findViewById(R.id.ivAddEvent);
            if (ivAddEvent != null) {
                ivAddEvent.setOnClickListener(v -> {
                    Log.d(TAG, "ivAddEvent clicked - launching CreateEventActivity");
                    Intent i = new Intent(requireActivity(), CreateEventActivity.class);
                    startActivity(i);
                });
            }
        } catch (Exception e) {
            Log.w(TAG, "Could not bind ivAddEvent: " + e.getMessage());
        }

        firebaseEventService = new FirebaseEventService();
        loadEvents();
    }

    /**
     * Binds view references from the inflated layout.
     *
     * @param view root view
     */
    private void initializeViews(View view) {
        eventsRecyclerView = view.findViewById(R.id.eventsRecyclerView);
        swipeRefreshLayout = view.findViewById(R.id.swipeRefreshLayout);
        emptyState = view.findViewById(R.id.emptyState);
        loadingState = view.findViewById(R.id.loadingState);
        searchInput = view.findViewById(R.id.searchInput);
        filterButton = view.findViewById(R.id.filterButton);
    }

    /**
     * Configures the RecyclerView and its adapter.
     */
    private void setupRecyclerView() {
        adapter = new EventAdapter(filteredEvents, this);
        eventsRecyclerView.setLayoutManager(new LinearLayoutManager(getContext()));
        eventsRecyclerView.setAdapter(adapter);
    }

    /**
     * Sets up pull-to-refresh behavior and colors.
     */
    private void setupSwipeRefresh() {
        swipeRefreshLayout.setOnRefreshListener(this::loadEvents);
        swipeRefreshLayout.setColorSchemeColors(ContextCompat.getColor(requireContext(), R.color.teal_700));
    }

    /**
     * Adds listeners for search text changes and filter button.
     */
    private void setupSearchAndFilter() {
        searchInput.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {
            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                filterEvents(s.toString());
            }

            @Override
            public void afterTextChanged(Editable s) {
            }
        });

        filterButton.setOnClickListener(v -> {
            // TODO: Implement advanced filtering (by date, price, location, etc.)
            Toast.makeText(getContext(), "Filter feature coming soon", Toast.LENGTH_SHORT).show();
        });
    }

    /**
     * Loads events from Firestore through the service and updates UI state accordingly.
     */
    private void loadEvents() {
        Log.d(TAG, "loadEvents() called");
        showLoadingState(true);

        // Changed to getAllEvents to fetch all events from the database
        firebaseEventService.getAllEvents(new FirebaseEventService.EventsCallback() {
            @Override
            public void onSuccess(List<Event> events) {
                Log.d(TAG, "onSuccess called with " + events.size() + " events");
                allEvents.clear();
                allEvents.addAll(events);
                filteredEvents.clear();
                filteredEvents.addAll(events);
                Log.d(TAG, "Updated adapter with " + filteredEvents.size() + " events");
                adapter.updateEvents(filteredEvents);
                updateUIState();
                swipeRefreshLayout.setRefreshing(false);
                showLoadingState(false);

                if (events.isEmpty()) {
                    Toast.makeText(getContext(), "No events found", Toast.LENGTH_SHORT).show();
                } else {
                    Toast.makeText(getContext(), "Loaded " + events.size() + " events", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onError(String errorMessage) {
                Log.e(TAG, "onError called: " + errorMessage);
                swipeRefreshLayout.setRefreshing(false);
                showLoadingState(false);
                Toast.makeText(getContext(), "Error loading events: " + errorMessage,
                        Toast.LENGTH_SHORT).show();
            }
        });
    }

    /**
     * Filters the in-memory event list by query and updates the adapter.
     *
     * @param query user-entered search term
     */
    private void filterEvents(String query) {
        if (query.isEmpty()) {
            filteredEvents.clear();
            filteredEvents.addAll(allEvents);
        } else {
            String queryLower = query.toLowerCase();
            filteredEvents.clear();
            filteredEvents.addAll(
                    allEvents.stream()
                            .filter(event -> event.getName().toLowerCase().contains(queryLower) ||
                                    event.getDescription().toLowerCase().contains(queryLower) ||
                                    event.getLocation().toLowerCase().contains(queryLower) ||
                                    event.getOrganizerName().toLowerCase().contains(queryLower))
                            .collect(Collectors.toList())
            );
        }
        adapter.updateEvents(filteredEvents);
        updateUIState();
    }

    /**
     * Toggles between empty and list states based on filtered results.
     */
    private void updateUIState() {
        if (filteredEvents.isEmpty()) {
            emptyState.setVisibility(View.VISIBLE);
            eventsRecyclerView.setVisibility(View.GONE);
        } else {
            emptyState.setVisibility(View.GONE);
            eventsRecyclerView.setVisibility(View.VISIBLE);
        }
    }

    /**
     * Shows a skeleton/loading state when appropriate.
     *
     * @param isLoading whether loading should be visible
     */
    private void showLoadingState(boolean isLoading) {
        if (isLoading && filteredEvents.isEmpty()) {
            loadingState.setVisibility(View.VISIBLE);
            eventsRecyclerView.setVisibility(View.GONE);
            emptyState.setVisibility(View.GONE);
        } else {
            loadingState.setVisibility(View.GONE);
        }
    }

    /**
     * Handles item click, navigating to the event details screen.
     *
     * @param event selected event
     */
    @Override
    public void onEventClick(Event event) {
        // Navigate to event detail fragment
        EventDetailFragment detailFragment = EventDetailFragment.newInstance(event.getId());
        getParentFragmentManager().beginTransaction()
                .replace(R.id.main, detailFragment)
                .addToBackStack(null)
                .commit();
    }
}

package ca.team.originkickoff.ui.fragments;

import android.os.Bundle;
import android.util.Log;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.ListenerRegistration;
import com.google.firebase.firestore.QueryDocumentSnapshot;
import com.google.firebase.firestore.QuerySnapshot;
import com.google.firebase.firestore.DocumentSnapshot;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import ca.team.originkickoff.R;
import ca.team.originkickoff.adapters.EventAdapter;
import ca.team.originkickoff.models.Event;
import ca.team.originkickoff.util.DeviceUtils;

public class EventsJoinedFragment extends Fragment implements EventAdapter.OnEventClickListener {
    private static final String TAG = "EventsJoinedFragment";
    private FirebaseFirestore db;
    private RecyclerView rv;
    private EventAdapter adapter;
    private final List<Event> events = new ArrayList<>();
    private final Map<String, String> eventStatusMap = new HashMap<>();

    private ListenerRegistration waitlistListener; // real-time updates
    private String currentUserId; // cached user id

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        int layoutId = getResources().getIdentifier("fragment_events_list", "layout", requireContext().getPackageName());
        View v;
        if (layoutId != 0) {
            v = inflater.inflate(layoutId, container, false);
        } else {
            // fallback to R if identifier lookup fails in this environment
            v = inflater.inflate(R.layout.fragment_events_list, container, false);
        }

        rv = v.findViewById(getResources().getIdentifier("rvEvents", "id", requireContext().getPackageName()));
        rv.setLayoutManager(new LinearLayoutManager(requireContext()));
        adapter = new EventAdapter(this);
        rv.setAdapter(adapter);

        db = FirebaseFirestore.getInstance();

        // Replace one-off load with real-time listener
        resolveUserAndListen();

        return v;
    }

    private void resolveUserAndListen() {
        String deviceId = DeviceUtils.getDeviceId(requireContext());
        if (deviceId == null) {
            Log.e(TAG, "Device ID null - cannot load joined events");
            adapter.setEvents(new ArrayList<>());
            return;
        }
        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnSuccessListener(q -> {
                    if (q.isEmpty()) {
                        Log.w(TAG, "No user found for device_id");
                        adapter.setEvents(new ArrayList<>());
                        return;
                    }
                    currentUserId = q.getDocuments().get(0).getId();
                    attachWaitlistListener();
                })
                .addOnFailureListener(e -> Log.e(TAG, "Failed to resolve user", e));
    }

    private void attachWaitlistListener() {
        if (currentUserId == null) return;
        if (waitlistListener != null) {
            waitlistListener.remove();
        }
        Log.d(TAG, "Attaching waitlist listener for user " + currentUserId);
        waitlistListener = db.collection("waiting_list_entries")
                .whereEqualTo("user_id", currentUserId)
                .whereEqualTo("state", "active")
                .addSnapshotListener((snap, err) -> {
                    if (err != null) {
                        Log.e(TAG, "Waitlist listener error", err);
                        return;
                    }
                    if (snap == null) {
                        adapter.setEvents(new ArrayList<>());
                        return;
                    }
                    List<String> eventIds = new ArrayList<>();
                    for (DocumentSnapshot d : snap.getDocuments()) {
                        String eid = d.getString("event_id");
                        if (eid != null) eventIds.add(eid);
                    }
                    Log.d(TAG, "Waitlist listener received " + eventIds.size() + " event IDs");
                    if (eventIds.isEmpty()) {
                        events.clear();
                        eventStatusMap.clear();
                        adapter.setEvents(new ArrayList<>());
                    } else {
                        fetchEventsInBatches(eventIds);
                    }
                });
    }

    // Batch fetch events (Firestore whereIn limit = 10) then enrich with lottery status
    private void fetchEventsInBatches(List<String> allEventIds) {
        events.clear();
        eventStatusMap.clear();
        // Fetch each event doc individually; simpler and avoids whereIn and batch completion race
        for (String eid : allEventIds) {
            db.collection("events").document(eid).get()
                    .addOnSuccessListener(this::handleEventDoc)
                    .addOnFailureListener(e -> Log.e(TAG, "Failed to load event doc " + eid, e));
        }
    }

    private void addOrReplaceEvent(Event event) {
        int idx = -1;
        for (int i = 0; i < events.size(); i++) {
            if (events.get(i).getId().equals(event.getId())) { idx = i; break; }
        }
        if (idx >= 0) {
            events.set(idx, event);
        } else {
            events.add(event);
        }
        adapter.setEventsWithStatus(new ArrayList<>(events), new HashMap<>(eventStatusMap));
    }

    private void handleEventDoc(DocumentSnapshot eventDoc) {
        if (eventDoc == null || !eventDoc.exists()) return;
        try {
            Event event = eventDoc.toObject(Event.class);
            if (event == null) return;
            event.setId(eventDoc.getId());
            String lotteryStatus = eventDoc.getString("lotteryStatus");
            if ("conducted".equals(lotteryStatus)) {
                // Determine user-specific status (invitation_status collection)
                db.collection("invitation_status")
                        .whereEqualTo("event_id", event.getId())
                        .whereEqualTo("user_id", currentUserId)
                        .limit(1)
                        .get()
                        .addOnSuccessListener(invSnap -> {
                            String status;
                            if (!invSnap.isEmpty()) {
                                String invitationStatus = invSnap.getDocuments().get(0).getString("status");
                                if ("chosen".equals(invitationStatus) || "enrolled".equals(invitationStatus)) {
                                    status = "YOU WERE SELECTED";
                                } else {
                                    status = "YOU WERE NOT SELECTED";
                                }
                            } else {
                                status = "YOU WERE NOT SELECTED";
                            }
                            eventStatusMap.put(event.getId(), status);
                            addOrReplaceEvent(event);
                        })
                        .addOnFailureListener(e -> {
                            Log.e(TAG, "Invitation status check failed", e);
                            eventStatusMap.put(event.getId(), "YOU WERE NOT SELECTED");
                            addOrReplaceEvent(event);
                        });
            } else {
                eventStatusMap.put(event.getId(), "YET TO DRAW");
                addOrReplaceEvent(event);
            }
        } catch (Exception ex) {
            Log.e(TAG, "Error parsing event doc", ex);
        }
    }

    @Override
    public void onDestroyView() {
        super.onDestroyView();
        if (waitlistListener != null) {
            waitlistListener.remove();
            waitlistListener = null;
        }
    }

    @Override
    public void onEventClick(Event event) {
        // Reuse EventDetailActivity
        startActivity(new android.content.Intent(requireContext(), ca.team.originkickoff.EventDetailActivity.class)
                .putExtra(ca.team.originkickoff.EventDetailActivity.EXTRA_EVENT_ID, event.getId()));
    }
}

/*
 * Shows events the current user has joined or is waitlisted for, with real-time status.
 * Merges event details with personalized invitation/lottery outcome statuses.
 */
package ca.team.originkickoff.ui.fragments;

import android.os.Bundle;
import android.util.Log;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.ListenerRegistration;
import com.google.firebase.firestore.QueryDocumentSnapshot;
import com.google.firebase.firestore.QuerySnapshot;
import com.google.firebase.firestore.DocumentSnapshot;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import ca.team.originkickoff.R;
import ca.team.originkickoff.adapters.EventAdapter;
import ca.team.originkickoff.models.Event;
import ca.team.originkickoff.util.DeviceUtils;

/**
 * Fragment listing events the user has joined, including dynamic lottery/invitation status.
 */
public class EventsJoinedFragment extends Fragment implements EventAdapter.OnEventClickListener {
    private static final String TAG = "EventsJoinedFragment";
    private FirebaseFirestore db;
    private RecyclerView rv;
    private EventAdapter adapter;
    private final List<Event> events = new ArrayList<>();
    private final Map<String, String> eventStatusMap = new HashMap<>();

    private ListenerRegistration waitlistListener; // real-time updates
    private String currentUserId; // cached user id

    /**
     * Inflates the list layout and configures RecyclerView with the adapter.
     *
     * @param inflater  layout inflater
     * @param container parent container
     * @param savedInstanceState state bundle
     * @return inflated root view
     */
    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        int layoutId = getResources().getIdentifier("fragment_events_list", "layout", requireContext().getPackageName());
        View v;
        if (layoutId != 0) {
            v = inflater.inflate(layoutId, container, false);
        } else {
            // fallback to R if identifier lookup fails in this environment
            v = inflater.inflate(R.layout.fragment_events_list, container, false);
        }

        rv = v.findViewById(getResources().getIdentifier("rvEvents", "id", requireContext().getPackageName()));
        rv.setLayoutManager(new LinearLayoutManager(requireContext()));
        adapter = new EventAdapter(this);
        rv.setAdapter(adapter);

        db = FirebaseFirestore.getInstance();

        // Replace one-off load with real-time listener
        resolveUserAndListen();

        return v;
    }

    /**
     * Resolves the current user and attaches the real-time waitlist listener.
     */
    private void resolveUserAndListen() {
        String deviceId = DeviceUtils.getDeviceId(requireContext());
        if (deviceId == null) {
            Log.e(TAG, "Device ID null - cannot load joined events");
            adapter.setEvents(new ArrayList<>());
            return;
        }
        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnSuccessListener(q -> {
                    if (q.isEmpty()) {
                        Log.w(TAG, "No user found for device_id");
                        adapter.setEvents(new ArrayList<>());
                        return;
                    }
                    currentUserId = q.getDocuments().get(0).getId();
                    attachWaitlistListener();
                })
                .addOnFailureListener(e -> Log.e(TAG, "Failed to resolve user", e));
    }

    /**
     * Subscribes to active waitlist entries to keep the joined list in sync.
     */
    private void attachWaitlistListener() {
        if (currentUserId == null) return;
        if (waitlistListener != null) {
            waitlistListener.remove();
        }
        Log.d(TAG, "Attaching waitlist listener for user " + currentUserId);
        waitlistListener = db.collection("waiting_list_entries")
                .whereEqualTo("user_id", currentUserId)
                .whereEqualTo("state", "active")
                .addSnapshotListener((snap, err) -> {
                    if (err != null) {
                        Log.e(TAG, "Waitlist listener error", err);
                        return;
                    }
                    if (snap == null) {
                        adapter.setEvents(new ArrayList<>());
                        return;
                    }
                    List<String> eventIds = new ArrayList<>();
                    for (DocumentSnapshot d : snap.getDocuments()) {
                        String eid = d.getString("event_id");
                        if (eid != null) eventIds.add(eid);
                    }
                    Log.d(TAG, "Waitlist listener received " + eventIds.size() + " event IDs");
                    if (eventIds.isEmpty()) {
                        events.clear();
                        eventStatusMap.clear();
                        adapter.setEvents(new ArrayList<>());
                    } else {
                        fetchEventsInBatches(eventIds);
                    }
                });
    }

    /**
     * Fetches event documents referenced by waitlist entries and updates the list.
     *
     * @param allEventIds event IDs from the user's waitlist entries
     */
    private void fetchEventsInBatches(List<String> allEventIds) {
        events.clear();
        eventStatusMap.clear();
        // Fetch each event doc individually; simpler and avoids whereIn and batch completion race
        for (String eid : allEventIds) {
            db.collection("events").document(eid).get()
                    .addOnSuccessListener(this::handleEventDoc)
                    .addOnFailureListener(e -> Log.e(TAG, "Failed to load event doc " + eid, e));
        }
    }

    /**
     * Adds or replaces an event in the aggregated list and refreshes the adapter.
     *
     * @param event event to upsert in the list
     */
    private void addOrReplaceEvent(Event event) {
        int idx = -1;
        for (int i = 0; i < events.size(); i++) {
            if (events.get(i).getId().equals(event.getId())) { idx = i; break; }
        }
        if (idx >= 0) {
            events.set(idx, event);
        } else {
            events.add(event);
        }
        adapter.setEventsWithStatus(new ArrayList<>(events), new HashMap<>(eventStatusMap));
    }

    /**
     * Parses an event document, determines personalized status, and updates the list.
     *
     * @param eventDoc Firestore document for the event
     */
    private void handleEventDoc(DocumentSnapshot eventDoc) {
        if (eventDoc == null || !eventDoc.exists()) return;
        try {
            Event event = eventDoc.toObject(Event.class);
            if (event == null) return;
            event.setId(eventDoc.getId());
            String lotteryStatus = eventDoc.getString("lotteryStatus");
            if ("conducted".equals(lotteryStatus)) {
                // Determine user-specific status (invitation_status collection)
                db.collection("invitation_status")
                        .whereEqualTo("event_id", event.getId())
                        .whereEqualTo("user_id", currentUserId)
                        .limit(1)
                        .get()
                        .addOnSuccessListener(invSnap -> {
                            String status;
                            if (!invSnap.isEmpty()) {
                                String invitationStatus = invSnap.getDocuments().get(0).getString("status");
                                if ("chosen".equals(invitationStatus) || "enrolled".equals(invitationStatus)) {
                                    status = "YOU WERE SELECTED";
                                } else {
                                    status = "YOU WERE NOT SELECTED";
                                }
                            } else {
                                status = "YOU WERE NOT SELECTED";
                            }
                            eventStatusMap.put(event.getId(), status);
                            addOrReplaceEvent(event);
                        })
                        .addOnFailureListener(e -> {
                            Log.e(TAG, "Invitation status check failed", e);
                            eventStatusMap.put(event.getId(), "YOU WERE NOT SELECTED");
                            addOrReplaceEvent(event);
                        });
            } else {
                eventStatusMap.put(event.getId(), "YET TO DRAW");
                addOrReplaceEvent(event);
            }
        } catch (Exception ex) {
            Log.e(TAG, "Error parsing event doc", ex);
        }
    }

    /**
     * Cleans up listeners on view destruction.
     */
    @Override
    public void onDestroyView() {
        super.onDestroyView();
        if (waitlistListener != null) {
            waitlistListener.remove();
            waitlistListener = null;
        }
    }

    /**
     * Handles click on an event to show details.
     *
     * @param event selected event
     */
    @Override
    public void onEventClick(Event event) {
        // Reuse EventDetailActivity
        startActivity(new android.content.Intent(requireContext(), ca.team.originkickoff.EventDetailActivity.class)
                .putExtra(ca.team.originkickoff.EventDetailActivity.EXTRA_EVENT_ID, event.getId()));
    }
}

package ca.team.originkickoff.ui.fragments;

import android.os.Bundle;
import android.util.Log;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.QueryDocumentSnapshot;

import java.util.ArrayList;
import java.util.List;

import ca.team.originkickoff.R;
import ca.team.originkickoff.adapters.OrganizedEventAdapter;
import ca.team.originkickoff.models.Event;
import ca.team.originkickoff.util.DeviceUtils;

public class EventsOrganizedFragment extends Fragment implements OrganizedEventAdapter.OnEventClickListener {
    private static final String TAG = "EventsOrganizedFrag";
    private FirebaseFirestore db;
    private RecyclerView rv;
    private OrganizedEventAdapter adapter;
    private final List<Event> events = new ArrayList<>();

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        int layoutId = getResources().getIdentifier("fragment_events_list", "layout", requireContext().getPackageName());
        View v;
        if (layoutId != 0) {
            v = inflater.inflate(layoutId, container, false);
        } else {
            v = inflater.inflate(R.layout.fragment_events_list, container, false);
        }

        rv = v.findViewById(getResources().getIdentifier("rvEvents", "id", requireContext().getPackageName()));
        rv.setLayoutManager(new LinearLayoutManager(requireContext()));
        adapter = new OrganizedEventAdapter(this);
        rv.setAdapter(adapter);

        db = FirebaseFirestore.getInstance();

        loadOrganizedEvents();

        return v;
    }

    private void loadOrganizedEvents() {
        // Get current user ID
        String deviceId = DeviceUtils.getDeviceId(requireContext());
        if (deviceId == null) {
            Toast.makeText(requireContext(), "Unable to identify user", Toast.LENGTH_SHORT).show();
            adapter.setEvents(new ArrayList<>());
            return;
        }

        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnSuccessListener(userSnapshots -> {
                    if (userSnapshots.isEmpty()) {
                        Log.w(TAG, "No user found for device_id");
                        adapter.setEvents(new ArrayList<>());
                        return;
                    }

                    String userId = userSnapshots.getDocuments().get(0).getId();
                    // Support multiple field spellings
                    Boolean isOrganizer = userSnapshots.getDocuments().get(0).getBoolean("is_organizer");
                    if (isOrganizer == null) isOrganizer = userSnapshots.getDocuments().get(0).getBoolean("is_organiser");
                    if (isOrganizer == null) {
                        Object camel = userSnapshots.getDocuments().get(0).get("isOrganizer");
                        if (camel instanceof Boolean) isOrganizer = (Boolean) camel;
                    }

                    if (isOrganizer == null || !isOrganizer) {
                        // Fallback: infer organizer role if any events exist with organizerId equal to either userId or deviceId
                        List<String> possibleIds = new java.util.ArrayList<>();
                        possibleIds.add(userId);
                        if (!deviceId.equals(userId)) possibleIds.add(deviceId);
                        db.collection("events")
                                .whereIn("organizerId", possibleIds)
                                .limit(1)
                                .get()
                                .addOnSuccessListener(eventSnap -> {
                                    if (!eventSnap.isEmpty()) {
                                        Log.d(TAG, "User inferred as organizer via existing events");
                                        loadEventsForOrganizerIds(possibleIds);
                                    } else {
                                        Log.d(TAG, "User is not an organizer (no matching events)");
                                        adapter.setEvents(new ArrayList<>());
                                    }
                                })
                                .addOnFailureListener(e -> {
                                    Log.e(TAG, "Organizer inference query failed", e);
                                    adapter.setEvents(new ArrayList<>());
                                });
                    } else {
                        // Normal path: user explicitly marked organizer
                        List<String> organizerIds = new java.util.ArrayList<>();
                        organizerIds.add(userId);
                        if (!deviceId.equals(userId)) organizerIds.add(deviceId); // include legacy id variant
                        loadEventsForOrganizerIds(organizerIds);
                    }
                })
                .addOnFailureListener(e -> {
                    Log.e(TAG, "Error loading user", e);
                    Toast.makeText(requireContext(), "Error loading user: " + e.getMessage(), Toast.LENGTH_SHORT).show();
                });
    }

    private void loadEventsForOrganizerIds(List<String> organizerIds) {
        // Use whereIn for up to two IDs; fallback to sequential if whereIn fails
        db.collection("events")
                .whereIn("organizerId", organizerIds)
                .get()
                .addOnSuccessListener(eventSnapshots -> {
                    events.clear();
                    for (QueryDocumentSnapshot doc : eventSnapshots) {
                        try {
                            Event e = doc.toObject(Event.class);
                            e.setId(doc.getId());
                            events.add(e);
                        } catch (Exception ex) {
                            Log.e(TAG, "Error parsing event", ex);
                        }
                    }
                    adapter.setEvents(events);
                })
                .addOnFailureListener(e -> {
                    Log.w(TAG, "whereIn failed, falling back to individual fetches: " + e.getMessage());
                    events.clear();
                    java.util.concurrent.atomic.AtomicInteger pending = new java.util.concurrent.atomic.AtomicInteger(organizerIds.size());
                    for (String oid : organizerIds) {
                        db.collection("events").whereEqualTo("organizerId", oid).get()
                                .addOnSuccessListener(snap -> {
                                    for (QueryDocumentSnapshot doc : snap) {
                                        try {
                                            Event ev = doc.toObject(Event.class);
                                            ev.setId(doc.getId());
                                            events.add(ev);
                                        } catch (Exception ex) {
                                            Log.e(TAG, "Parse error", ex);
                                        }
                                    }
                                    if (pending.decrementAndGet() == 0) adapter.setEvents(events);
                                })
                                .addOnFailureListener(err -> {
                                    Log.e(TAG, "Fallback organizerId query failed", err);
                                    if (pending.decrementAndGet() == 0) adapter.setEvents(events);
                                });
                    }
                });
    }

    @Override
    public void onEventClick(Event event) {
        startActivity(new android.content.Intent(requireContext(), ca.team.originkickoff.EventDetailActivity.class)
                .putExtra(ca.team.originkickoff.EventDetailActivity.EXTRA_EVENT_ID, event.getId()));
    }
}

/*
 * Shows events organized by the current user with real-time Firestore queries.
 * Helps organizers review and navigate into their own events.
 */
package ca.team.originkickoff.ui.fragments;

import android.os.Bundle;
import android.util.Log;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.QueryDocumentSnapshot;

import java.util.ArrayList;
import java.util.List;

import ca.team.originkickoff.R;
import ca.team.originkickoff.adapters.OrganizedEventAdapter;
import ca.team.originkickoff.models.Event;
import ca.team.originkickoff.util.DeviceUtils;

/**
 * Fragment that lists the events organized by the signed-in (device) user.
 */
public class EventsOrganizedFragment extends Fragment implements OrganizedEventAdapter.OnEventClickListener {
    private static final String TAG = "EventsOrganizedFrag";
    private FirebaseFirestore db;
    private RecyclerView rv;
    private OrganizedEventAdapter adapter;
    private final List<Event> events = new ArrayList<>();

    /**
     * Inflates the events list layout and initializes the RecyclerView and adapter.
     *
     * @param inflater  layout inflater
     * @param container parent view group
     * @param savedInstanceState state bundle
     * @return inflated root view
     */
    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        int layoutId = getResources().getIdentifier("fragment_events_list", "layout", requireContext().getPackageName());
        View v;
        if (layoutId != 0) {
            v = inflater.inflate(layoutId, container, false);
        } else {
            v = inflater.inflate(R.layout.fragment_events_list, container, false);
        }

        rv = v.findViewById(getResources().getIdentifier("rvEvents", "id", requireContext().getPackageName()));
        rv.setLayoutManager(new LinearLayoutManager(requireContext()));
        adapter = new OrganizedEventAdapter(this);
        rv.setAdapter(adapter);

        db = FirebaseFirestore.getInstance();

        loadOrganizedEvents();

        return v;
    }

    /**
     * Resolves the user's organizer role and queries events they own.
     */
    private void loadOrganizedEvents() {
        // Get current user ID
        String deviceId = DeviceUtils.getDeviceId(requireContext());
        if (deviceId == null) {
            Toast.makeText(requireContext(), "Unable to identify user", Toast.LENGTH_SHORT).show();
            adapter.setEvents(new ArrayList<>());
            return;
        }

        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnSuccessListener(userSnapshots -> {
                    if (userSnapshots.isEmpty()) {
                        Log.w(TAG, "No user found for device_id");
                        adapter.setEvents(new ArrayList<>());
                        return;
                    }

                    String userId = userSnapshots.getDocuments().get(0).getId();
                    // Support multiple field spellings
                    Boolean isOrganizer = userSnapshots.getDocuments().get(0).getBoolean("is_organizer");
                    if (isOrganizer == null) isOrganizer = userSnapshots.getDocuments().get(0).getBoolean("is_organiser");
                    if (isOrganizer == null) {
                        Object camel = userSnapshots.getDocuments().get(0).get("isOrganizer");
                        if (camel instanceof Boolean) isOrganizer = (Boolean) camel;
                    }

                    if (isOrganizer == null || !isOrganizer) {
                        // Fallback: infer organizer role if any events exist with organizerId equal to either userId or deviceId
                        List<String> possibleIds = new java.util.ArrayList<>();
                        possibleIds.add(userId);
                        if (!deviceId.equals(userId)) possibleIds.add(deviceId);
                        db.collection("events")
                                .whereIn("organizerId", possibleIds)
                                .limit(1)
                                .get()
                                .addOnSuccessListener(eventSnap -> {
                                    if (!eventSnap.isEmpty()) {
                                        Log.d(TAG, "User inferred as organizer via existing events");
                                        loadEventsForOrganizerIds(possibleIds);
                                    } else {
                                        Log.d(TAG, "User is not an organizer (no matching events)");
                                        adapter.setEvents(new ArrayList<>());
                                    }
                                })
                                .addOnFailureListener(e -> {
                                    Log.e(TAG, "Organizer inference query failed", e);
                                    adapter.setEvents(new ArrayList<>());
                                });
                    } else {
                        // Normal path: user explicitly marked organizer
                        List<String> organizerIds = new java.util.ArrayList<>();
                        organizerIds.add(userId);
                        if (!deviceId.equals(userId)) organizerIds.add(deviceId); // include legacy id variant
                        loadEventsForOrganizerIds(organizerIds);
                    }
                })
                .addOnFailureListener(e -> {
                    Log.e(TAG, "Error loading user", e);
                    Toast.makeText(requireContext(), "Error loading user: " + e.getMessage(), Toast.LENGTH_SHORT).show();
                });
    }

    /**
     * Loads events for any of the provided organizer IDs, with a fallback path if whereIn fails.
     *
     * @param organizerIds one or more possible organizer identifiers
     */
    private void loadEventsForOrganizerIds(List<String> organizerIds) {
        // Use whereIn for up to two IDs; fallback to sequential if whereIn fails
        db.collection("events")
                .whereIn("organizerId", organizerIds)
                .get()
                .addOnSuccessListener(eventSnapshots -> {
                    events.clear();
                    for (QueryDocumentSnapshot doc : eventSnapshots) {
                        try {
                            Event e = doc.toObject(Event.class);
                            e.setId(doc.getId());
                            events.add(e);
                        } catch (Exception ex) {
                            Log.e(TAG, "Error parsing event", ex);
                        }
                    }
                    adapter.setEvents(events);
                })
                .addOnFailureListener(e -> {
                    Log.w(TAG, "whereIn failed, falling back to individual fetches: " + e.getMessage());
                    events.clear();
                    java.util.concurrent.atomic.AtomicInteger pending = new java.util.concurrent.atomic.AtomicInteger(organizerIds.size());
                    for (String oid : organizerIds) {
                        db.collection("events").whereEqualTo("organizerId", oid).get()
                                .addOnSuccessListener(snap -> {
                                    for (QueryDocumentSnapshot doc : snap) {
                                        try {
                                            Event ev = doc.toObject(Event.class);
                                            ev.setId(doc.getId());
                                            events.add(ev);
                                        } catch (Exception ex) {
                                            Log.e(TAG, "Parse error", ex);
                                        }
                                    }
                                    if (pending.decrementAndGet() == 0) adapter.setEvents(events);
                                })
                                .addOnFailureListener(err -> {
                                    Log.e(TAG, "Fallback organizerId query failed", err);
                                    if (pending.decrementAndGet() == 0) adapter.setEvents(events);
                                });
                    }
                });
    }

    /**
     * Handles click on an event to open its details.
     *
     * @param event selected event
     */
    @Override
    public void onEventClick(Event event) {
        startActivity(new android.content.Intent(requireContext(), ca.team.originkickoff.EventDetailActivity.class)
                .putExtra(ca.team.originkickoff.EventDetailActivity.EXTRA_EVENT_ID, event.getId()));
    }
}

package ca.team.originkickoff.ui.fragments;

import android.os.Bundle;
import android.util.Log;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ProgressBar;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.QueryDocumentSnapshot;

import java.util.ArrayList;
import java.util.List;

import ca.team.originkickoff.R;
import ca.team.originkickoff.adapters.InvitationAdapter;
import ca.team.originkickoff.models.InvitationStatus;

/**
 * Fragment for displaying list of invitations by status (chosen/cancelled/enrolled)
 */
public class InvitationListFragment extends Fragment {
    private static final String TAG = "InvitationListFragment";
    private static final String ARG_EVENT_ID = "event_id";
    private static final String ARG_STATUS = "status";

    private String eventId;
    private String status;
    private RecyclerView recyclerView;
    private ProgressBar progressBar;
    private TextView tvEmpty;
    private InvitationAdapter adapter;

    public static InvitationListFragment newInstance(String eventId, String status) {
        InvitationListFragment fragment = new InvitationListFragment();
        Bundle args = new Bundle();
        args.putString(ARG_EVENT_ID, eventId);
        args.putString(ARG_STATUS, status);
        fragment.setArguments(args);
        return fragment;
    }

    @Override
    public void onCreate(@Nullable Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        if (getArguments() != null) {
            eventId = getArguments().getString(ARG_EVENT_ID);
            status = getArguments().getString(ARG_STATUS);
        }
    }

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {
        View view = inflater.inflate(R.layout.fragment_invitation_list, container, false);

        recyclerView = view.findViewById(R.id.recycler_view);
        progressBar = view.findViewById(R.id.progress_bar);
        tvEmpty = view.findViewById(R.id.tv_empty);

        recyclerView.setLayoutManager(new LinearLayoutManager(getContext()));
        adapter = new InvitationAdapter(new ArrayList<>());
        recyclerView.setAdapter(adapter);

        loadInvitations();

        return view;
    }

    private void loadInvitations() {
        progressBar.setVisibility(View.VISIBLE);
        tvEmpty.setVisibility(View.GONE);

        FirebaseFirestore.getInstance()
                .collection("invitation_status")
                .whereEqualTo("event_id", eventId)
                .whereEqualTo("status", status)
                .addSnapshotListener((snapshots, error) -> {
                    progressBar.setVisibility(View.GONE);

                    if (error != null) {
                        Log.e(TAG, "Error loading invitations", error);
                        showEmpty();
                        return;
                    }

                    if (snapshots != null && !snapshots.isEmpty()) {
                        List<InvitationStatus> invitations = new ArrayList<>();
                        for (QueryDocumentSnapshot doc : snapshots) {
                            InvitationStatus invitation = doc.toObject(InvitationStatus.class);
                            invitations.add(invitation);
                        }
                        adapter.updateData(invitations);
                        tvEmpty.setVisibility(View.GONE);
                    } else {
                        showEmpty();
                    }
                });
    }

    private void showEmpty() {
        tvEmpty.setVisibility(View.VISIBLE);
        String message;
        switch (status) {
            case "chosen":
                message = "No users selected yet";
                break;
            case "cancelled":
                message = "No cancellations";
                break;
            case "enrolled":
                message = "No enrollments yet";
                break;
            default:
                message = "No results";
        }
        tvEmpty.setText(message);
    }
}

/*
 * Displays invitations for an event filtered by status (chosen/cancelled/enrolled).
